    @Test
    public void ownedProfileListenerWaitsForAcceptedSocketAlreadyQueuedToWorkers() throws Exception {
        try (Fixture fixture = new Fixture(false, false, true)) {
            fixture.listeners.get(0).close().sync();
            var budget = new ProfileReceiveBudget(524288, 131072, 262144, 1, 8, 8);
            var listener = new SegmentProfileListener(fixture.nodes.get(0), fixture.serverTls, budget,
                    new SegmentProfileListener.Settings(131072, 64, "socket-test", 0),
                    new InetSocketAddress("127.0.0.1", 0), fixture.acceptor, fixture.worker,
                    fixture.controlConfigs.get(0), null);
            var release = new CountDownLatch(1);
            var blocked = new CountDownLatch(2);
            var accepted = new CountDownLatch(1);
            try {
                var address = listener.bound().get(5, TimeUnit.SECONDS);
                var field = SegmentProfileListener.class.getDeclaredField("listener");
                field.setAccessible(true);
                Channel parent = (Channel) field.get(listener);
                parent.eventLoop().submit(() -> parent.pipeline().addFirst("observeAccepted",
                        new io.netty.channel.ChannelInboundHandlerAdapter() {
                            @Override
                            public void channelRead(ChannelHandlerContext context, Object message) throws Exception {
                                accepted.countDown();
                                context.fireChannelRead(message);
                            }
                        })).get(5, TimeUnit.SECONDS);
                for (var loop : fixture.worker) {
                    loop.execute(() -> {
                        blocked.countDown();
                        try {
                            assertTrue(release.await(20, TimeUnit.SECONDS));
                        } catch (InterruptedException interrupted) {
                            Thread.currentThread().interrupt();
                            throw new IllegalStateException(interrupted);
                        }
                    });
                }
                assertTrue(blocked.await(5, TimeUnit.SECONDS));
                try (var connection = new java.net.Socket()) {
                    connection.connect(address, 1000);
                    assertTrue(accepted.await(5, TimeUnit.SECONDS));
                    parent.eventLoop().submit(() -> { }).get(5, TimeUnit.SECONDS);
                    assertEquals(1, budget.usedConnections(ProfileReceiveBudget.Lane.UNCLASSIFIED));
                    long prepaid = budget.used(ProfileReceiveBudget.Lane.UNCLASSIFIED);
                    assertTrue("Connection metadata was not prepaid: " + prepaid, prepaid > 64);
                    // Exhausted admission closes on the acceptor, while both worker loops remain blocked.
                    try (var refused = new java.net.Socket()) {
                        refused.connect(address, 1000);
                        refused.setSoTimeout(1000);
                        assertEquals(-1, refused.getInputStream().read());
                    }
                    assertEquals(1, budget.usedConnections(ProfileReceiveBudget.Lane.UNCLASSIFIED));
                    assertEquals(prepaid, budget.used(ProfileReceiveBudget.Lane.UNCLASSIFIED));
                    var closing = listener.closeAsync();
                    assertThrows(java.util.concurrent.TimeoutException.class,
                            () -> closing.get(100, TimeUnit.MILLISECONDS));
                    assertEquals(1, budget.usedConnections(ProfileReceiveBudget.Lane.UNCLASSIFIED));
                    assertEquals(prepaid, budget.used(ProfileReceiveBudget.Lane.UNCLASSIFIED));
                    release.countDown();
                    closing.get(5, TimeUnit.SECONDS);
                    connection.setSoTimeout(1000);
                    assertEquals(-1, connection.getInputStream().read());
                    for (var lane : ProfileReceiveBudget.Lane.values()) {
                        assertEquals(0, budget.usedConnections(lane));
                        assertEquals(0, budget.used(lane));
                    }
                }
            } finally {
                release.countDown();
                listener.closeAsync().get(5, TimeUnit.SECONDS);
            }
        }
    }

    private static final class HeldServicePublicationClient extends ZooKeeper {
        final CountDownLatch submitted = new CountDownLatch(1);
        final CountDownLatch release = new CountDownLatch(1);
        volatile boolean armed;
        volatile boolean loseReadinessReply;
        volatile boolean loseWritableReply;
        final AtomicInteger lostReadinessReplies = new AtomicInteger();
        final AtomicInteger lostWritableReplies = new AtomicInteger();

        HeldServicePublicationClient(String connect, ZooKeeperWatcherBase watcher) throws Exception {
            super(connect, 10000, watcher);
            watcher.waitForConnection();
        }

        @Override
        public void multi(Iterable<org.apache.zookeeper.Op> operations,
                org.apache.zookeeper.AsyncCallback.MultiCallback callback, Object context) {
            var copied = new ArrayList<org.apache.zookeeper.Op>();
            operations.forEach(copied::add);
            if (armed && copied.stream().anyMatch(op -> op.getPath().startsWith("/socket-service-readiness/"))) {
                armed = false;
                submitted.countDown();
                await(release);
            }
            boolean readiness = copied.stream().anyMatch(op ->
                    (op.getType() == org.apache.zookeeper.ZooDefs.OpCode.create
                            || op.getType() == org.apache.zookeeper.ZooDefs.OpCode.setData)
                            && op.getPath().startsWith("/socket-service-readiness/")
                            && op.getPath().substring("/socket-service-readiness/".length()).indexOf('/') < 0);
            boolean writable = copied.stream().anyMatch(op ->
                    op.getType() == org.apache.zookeeper.ZooDefs.OpCode.create && op.getPath().endsWith("/writable"));
            super.multi(copied, (code, path, ignored, results) -> {
                boolean lost = false;
                if (code == org.apache.zookeeper.KeeperException.Code.OK.intValue()) {
                    if (readiness && loseReadinessReply) {
                        loseReadinessReply = false;
                        lostReadinessReplies.incrementAndGet();
                        lost = true;
                    } else if (writable && loseWritableReply) {
                        loseWritableReply = false;
                        lostWritableReplies.incrementAndGet();
                        lost = true;
                    }
                }
                callback.processResult(lost ? org.apache.zookeeper.KeeperException.Code.CONNECTIONLOSS.intValue()
                        : code, path, context, results);
            }, context);
        }
    }

    private final class RestoreCrashTarget implements AutoCloseable {
        final Process process;
        final Path output;
        final InetSocketAddress address;

        RestoreCrashTarget(Fixture fixture, ServiceEpisode episode) throws Exception {
            fixture.listeners.get(3).close().sync();
            fixture.nodes.get(3).close();
            Path directory = temporary.newFolder().toPath();
            Path properties = directory.resolve("target.properties");
            Path ready = directory.resolve("ready");
            output = directory.resolve("child.log");
            var values = new java.util.Properties();
            episode.bootstrapConfiguration.getKeys().forEachRemaining(name -> values.setProperty(name,
                    episode.bootstrapConfiguration.getString(name)));
            try (var stream = Files.newOutputStream(properties)) {
                values.store(stream, "Disposable restore crash target");
            }
            process = new ProcessBuilder(Path.of(System.getProperty("java.home"), "bin", "java").toString(),
                    "-Xmx128m", "-XX:MaxDirectMemorySize=64m", "-cp", System.getProperty("java.class.path"),
                    RestoreTargetCrashProbe.class.getName(), properties.toString(), ready.toString())
                    .redirectErrorStream(true).redirectOutput(output.toFile()).start();
            try {
                long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(20);
                while (!Files.exists(ready) && process.isAlive() && System.nanoTime() < deadline) {
                    LockSupport.parkNanos(TimeUnit.MILLISECONDS.toNanos(2));
                }
                assertTrue(Files.readString(output), Files.exists(ready) && process.isAlive());
                address = new InetSocketAddress("127.0.0.1", Integer.parseInt(Files.readString(ready)));
            } catch (Exception | Error failure) {
                close();
                throw failure;
            }
        }

        void awaitCrash(ServiceEpisode episode) throws Exception {
            assertTrue(Files.readString(output), process.waitFor(15, TimeUnit.SECONDS));
            String log = Files.readString(output);
            System.out.println("UW_RESTORE_CRASH_CHILD " + log);
            assertEquals(log, 23, process.exitValue());
            assertTrue(log, log.contains("RESTORE_RECOVERY_DATA_DURABLE_HALT"));
            long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(15);
            while (episode.persistent.readPeer("socket3:3181").status()
                    != org.apache.bookkeeper.common.profile.startup.ProfileRegistrationStore.ReadStatus.NOT_FOUND
                    && System.nanoTime() < deadline) {
                LockSupport.parkNanos(TimeUnit.MILLISECONDS.toNanos(10));
            }
            assertEquals(org.apache.bookkeeper.common.profile.startup.ProfileRegistrationStore.ReadStatus.NOT_FOUND,
                    episode.persistent.readPeer("socket3:3181").status());
        }

        @Override
        public void close() throws Exception {
            if (process.isAlive()) {
                process.destroyForcibly();
                assertTrue(Files.readString(output), process.waitFor(5, TimeUnit.SECONDS));
            }
        }
    }

    /** The real target service halts after its first successful recovery DATA result, without Java cleanup. */
    public static final class RestoreTargetCrashProbe {
        public static void main(String[] args) throws Exception {
            if (args.length != 2) {
                throw new IllegalArgumentException("Expected target properties and ready file");
            }
            var configuration = new ServerConfiguration();
            configuration.loadConf(Path.of(args[0]).toUri().toURL());
            var directory = Path.of(configuration.getString(SegmentProfileService.CONFIG_PREFIX + "Directory"));
            var config = new IsolatedSegmentConfig(directory, 1, 1, 1, 4L * 1024 * 1024,
                    4096, 1024, 16, "FILE_CHANNEL", "OFF", "SYSTEM", "PARK");
            var identity = new SegmentFileHeader(new StorageIncarnation(bytes(16, 8)),
                    new UUID(0, 9), BookieId.parse("socket3:3181"));
            var policy = servicePolicy(config, identity, 1);
            var settings = new SegmentProfileOwnedResources.Settings(policy,
                    "/socket-service-required-3-" + Integer.toUnsignedString(directory.hashCode()),
                    "/socket-service-readiness", "/socket-initial", ZooDefs.Ids.OPEN_ACL_UNSAFE,
                    "ledger-profile", 4, Duration.ofSeconds(5), Duration.ofMillis(100), 2, 4, 64);
            var tlsConfiguration = new ServerConfiguration();
            tlsConfiguration.setTLSKeyStoreType("PEM");
            tlsConfiguration.setTLSKeyStore(certificate("server-key.pem"));
            tlsConfiguration.setTLSCertificatePath(certificate("server-san-cert.pem"));
            tlsConfiguration.setTLSTrustStoreType("PEM");
            tlsConfiguration.setTLSTrustStore(certificate("client-cert.pem"));
            var tls = TLSContextFactory.forProfileServer();
            tls.init(SecurityHandlerFactory.NodeType.Server, tlsConfiguration, UnpooledByteBufAllocator.DEFAULT);
            var principal = socketProfilePrincipal();
            var read = new SegmentProfileReadConfig((caller, query) -> caller.equals(principal),
                    (caller, query) -> caller.equals(principal));
            long controlWorkingSet = SegmentControlCapacity.required(config, ServiceEpisode.CONTROL_LOG_BYTES);
            var service = SegmentProfileService.withOwnedResources(configuration,
                    new SecretKeySpec(bytes(32, 7), "AES"), VALIDATOR, settings, tls,
                    new ProfileReceiveBudget(SegmentControlCapacity.sum(4L * 1024 * 1024, controlWorkingSet,
                            serviceRestartHeadroom(config), serviceInputMetadataBytes(config),
                            serviceDriverMetadataBytes(config)),
                            131072 + controlWorkingSet, 262144, 8, 8, 8),
                    131072, 64, "socket-test", new InetSocketAddress("127.0.0.1", 0),
                    (caller, operation) -> caller.equals(principal),
                    (caller, scope, authority) -> caller.equals(principal) && scope.equals(authority.scope())
                            ? Decision.ALLOW : Decision.DENY, read);
            var address = service.start(true);
            var listenerField = SegmentProfileService.class.getDeclaredField("listener");
            listenerField.setAccessible(true);
            var channelField = SegmentProfileListener.class.getDeclaredField("listener");
            channelField.setAccessible(true);
            var listener = (Channel) channelField.get(listenerField.get(service));
            listener.eventLoop().submit(() -> listener.pipeline().addFirst("observeCrashTarget",
                    new io.netty.channel.ChannelInboundHandlerAdapter() {
                        @Override
                        public void channelRead(ChannelHandlerContext context, Object message) throws Exception {
                            var child = (Channel) message;
                            child.pipeline().addLast(new io.netty.channel.ChannelInboundHandlerAdapter() {
                                @Override
                                public void channelActive(ChannelHandlerContext active) throws Exception {
                                    var ssl = active.pipeline().context(SslHandler.class);
                                    active.pipeline().addAfter(ssl.name(), "haltDurableRecovery",
                                            new ChannelOutboundHandlerAdapter() {
                                                @Override
                                                public void write(ChannelHandlerContext ctx, Object response,
                                                        ChannelPromise promise) throws Exception {
                                                    if (response instanceof ByteBuf frame
                                                            && frame.getUnsignedShort(frame.readerIndex() + 14)
                                                                == ProfileOperation.ADD_RECOVERY.wireValue()) {
                                                        byte[] body = new byte[ProfileStatus.ENCODED_LENGTH];
                                                        frame.getBytes(frame.readerIndex() + 36, body);
                                                        var status = ProfileStatus.decode(body);
                                                        if (status.statusClass() == ProfileStatus.StatusClass.OK
                                                                && status.durableResult()
                                                                    == ProfileStatus.DurableResult.APPLIED) {
                                                            System.out.println("RESTORE_RECOVERY_DATA_DURABLE_HALT");
                                                            System.out.flush();
                                                            Runtime.getRuntime().halt(23);
                                                        }
                                                    }
                                                    ctx.write(response, promise);
                                                }
                                            });
                                    active.fireChannelActive();
                                }
                            });
                            context.fireChannelRead(message);
                        }
                    })).get(5, TimeUnit.SECONDS);
            Path ready = Path.of(args[1]);
            Path pending = ready.resolveSibling("ready.pending");
            Files.writeString(pending, Integer.toString(address.getPort()));
            Files.move(pending, ready, java.nio.file.StandardCopyOption.ATOMIC_MOVE);
            new CountDownLatch(1).await();
        }
    }

    private static ProfilePrincipal socketProfilePrincipal() throws Exception {
        java.security.cert.X509Certificate certificate;
        try (var input = Files.newInputStream(Path.of(certificate("client-cert.pem")))) {
            certificate = (java.security.cert.X509Certificate)
                    java.security.cert.CertificateFactory.getInstance("X.509").generateCertificate(input);
        }
        return new ProfilePrincipal(ProfilePrincipal.MappingMode.TRUST_DOMAIN_ISSUER_PLUS_SUBJECT,
                "socket-test", certificate.getIssuerX500Principal().getName(
                        javax.security.auth.x500.X500Principal.CANONICAL),
                certificate.getSubjectX500Principal().getName(javax.security.auth.x500.X500Principal.CANONICAL));
    }

    private final class ServiceEpisode implements AutoCloseable {
        private static final long CONTROL_LOG_BYTES = 1024 * 1024;
        private static final long DATA_BYTES = 4L * 1024 * 1024 - 131072 - 262144;
        final long controlWorkingSetBytes;
        final long controlBytes;
        final long dataBytes;
        final ZooKeeperWatcherBase watcher = new ZooKeeperWatcherBase(10000, false);
        final ZooKeeper client;
        final ZKProfileStartupRequirementsStore requirements;
        final ZKProfileRegistrationStore persistent;
        final ZKProfileEphemeralRegistrationStore publisher;
        final SegmentProfileService service;
        final ProfileReceiveBudget budget;
        final IsolatedSegmentConfig config;
        final ServerConfiguration bootstrapConfiguration;
        final SegmentProfileService.Startup startup;
        final SegmentProfileService.Transport transport;
        final boolean ownsResources;
        SslContext ownedTlsContext;
        org.apache.bookkeeper.server.EmbeddedServer embedded;

        ServiceEpisode(Fixture fixture, int target, IsolatedSegmentConfig config,
                StartupReadinessInput requested, BookieCompatibilityFact requiredCompatibility,
                InetSocketAddress address, java.util.concurrent.ScheduledExecutorService scheduler) throws Exception {
            this(fixture, target, config, requested, requiredCompatibility, address, scheduler, false);
        }

        ServiceEpisode(Fixture fixture, int target, IsolatedSegmentConfig config,
                StartupReadinessInput requested, BookieCompatibilityFact requiredCompatibility,
                InetSocketAddress address, java.util.concurrent.ScheduledExecutorService scheduler,
                boolean holdPublication) throws Exception {
            this(fixture, target, config, requested, requiredCompatibility, address, scheduler, holdPublication, false);
        }

        ServiceEpisode(Fixture fixture, int target, IsolatedSegmentConfig config,
                StartupReadinessInput requested, BookieCompatibilityFact requiredCompatibility,
                InetSocketAddress address, java.util.concurrent.ScheduledExecutorService scheduler,
                boolean holdPublication, boolean ownsResources) throws Exception {
            this(fixture, target, config, requested, requiredCompatibility, address, scheduler,
                    holdPublication, ownsResources, 0);
        }

        private ServiceEpisode(Fixture fixture, int target, IsolatedSegmentConfig config,
                StartupReadinessInput requested, BookieCompatibilityFact requiredCompatibility,
                InetSocketAddress address, java.util.concurrent.ScheduledExecutorService scheduler,
                boolean holdPublication, boolean ownsResources, long additionalDataBytes) throws Exception {
            this(fixture, target, config, requested, requiredCompatibility, address, scheduler, holdPublication,
                    ownsResources, additionalDataBytes, 16);
        }

        private ServiceEpisode(Fixture fixture, int target, IsolatedSegmentConfig config,
                StartupReadinessInput requested, BookieCompatibilityFact requiredCompatibility,
                InetSocketAddress address, java.util.concurrent.ScheduledExecutorService scheduler,
                boolean holdPublication, boolean ownsResources, long additionalDataBytes, int indexedEntries)
                throws Exception {
            this.config = config;
            this.ownsResources = ownsResources;
            controlWorkingSetBytes = SegmentControlCapacity.required(config, CONTROL_LOG_BYTES);
            controlBytes = 131072 + controlWorkingSetBytes;
            long inputMetadataBytes = serviceInputMetadataBytes(config);
            long driverMetadataBytes = serviceDriverMetadataBytes(config);
            dataBytes = SegmentControlCapacity.sum(DATA_BYTES, additionalDataBytes,
                    inputMetadataBytes, driverMetadataBytes);
            budget = new ProfileReceiveBudget(SegmentControlCapacity.sum(4L * 1024 * 1024,
                    controlWorkingSetBytes, additionalDataBytes, inputMetadataBytes, driverMetadataBytes),
                    controlBytes, 262144, 8, 8, 8);
            client = holdPublication
                    ? new HeldServicePublicationClient(fixture.cluster.getZooKeeperConnectString(), watcher)
                    : new ZooKeeper(fixture.cluster.getZooKeeperConnectString(), 10000, watcher);
            watcher.waitForConnection();
            String root = SOCKET_SERVICE_READINESS;
            String requiredRoot = "/socket-service-required-" + target + "-"
                    + Integer.toUnsignedString(config.directory().hashCode());
            for (String path : List.of(root, requiredRoot)) {
                if (client.exists(path, false) == null) {
                    client.create(path, new byte[0], ZooDefs.Ids.OPEN_ACL_UNSAFE, CreateMode.PERSISTENT);
                }
            }
            var identity = fixture.identities.get(target);
            requirements = new ZKProfileStartupRequirementsStore(client, requiredRoot,
                    ZooDefs.Ids.OPEN_ACL_UNSAFE, Duration.ofSeconds(5));
            if (requiredCompatibility != null) {
                assertEquals(ZKProfileStartupRequirementsStore.ProvisionStatus.APPLIED,
                        requirements.provision(requiredCompatibility, requested.requiredDevices()));
            }
            persistent = new ZKProfileRegistrationStore(client, root, ZooDefs.Ids.OPEN_ACL_UNSAFE,
                    Duration.ofSeconds(5));
            publisher = new ZKProfileEphemeralRegistrationStore(client, root, identity.bookieId().toString(),
                    ZooDefs.Ids.OPEN_ACL_UNSAFE, Duration.ofSeconds(5));
            var source = new ZKProfileReservationStore(client, "/socket-initial", ZooDefs.Ids.OPEN_ACL_UNSAFE,
                    Duration.ofSeconds(5));
            assertEquals(org.apache.bookkeeper.common.profile.control.ProfileControlStore.ReadStatus.FOUND,
                    source.createInitialDeleteAssignment(new org.apache.bookkeeper.discover.profile
                            .ProfileDeleteRecord.Target(identity.bookieId().toString(), identity.incarnation().value()))
                            .status());
            var metadata = new ProfileLedgerMetadataStore(client, (AbstractZkLedgerManager) fixture.manager,
                    ZooDefs.Ids.OPEN_ACL_UNSAFE, Duration.ofSeconds(5));
            startup = new SegmentProfileService.Startup(requirements, requested, persistent, publisher,
                    source, metadata, watcher, "ledger-profile", scheduler, fixture.cold, 4,
                    Duration.ofSeconds(5), Duration.ofMillis(100));
            var control = fixture.controlConfigs.get(target);
            var read = new SegmentProfileReadConfig((caller, query) -> fixture.readAllowed.get()
                    && control.staticAuthorizer().allows(caller, ProfileControlOperation.INSTALL)
                    && fixture.permitsReadContext(query.context()),
                    (caller, query) -> fixture.readAllowed.get()
                    && control.staticAuthorizer().allows(caller, ProfileControlOperation.INSTALL)
                    && fixture.permitsReadContext(query.context()));
            transport = new SegmentProfileService.Transport(fixture.serverTls, budget,
                    131072, 64, "socket-test", requested.targetReadinessGeneration().value(),
                    address, fixture.acceptor, fixture.worker, control, read);
            var settings = new HashMap<>(serviceSettings(config));
            settings.put("IndexedEntries", indexedEntries);
            var properties = new java.util.Properties();
            settings.forEach((name, value) -> properties.setProperty(
                    SegmentProfileService.CONFIG_PREFIX + name, value.toString()));
            var input = temporary.newFolder().toPath().resolve("bookie.properties");
            try {
                try (var output = Files.newOutputStream(input)) {
                    properties.store(output, "Disposable Profile bootstrap bounds; authority is supplied separately");
                }
                bootstrapConfiguration = new ServerConfiguration();
                bootstrapConfiguration.loadConf(input.toUri().toURL());
                System.out.println("UW_PROFILE_CONFIG_RECEIPT " + new com.fasterxml.jackson.databind.ObjectMapper()
                        .writeValueAsString(Map.of("settings", settings, "propertiesSha256",
                                java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256")
                                        .digest(Files.readAllBytes(input))), "schema", 1)));
            } finally {
                Files.deleteIfExists(input);
            }
            if (ownsResources) {
                configureOwnedProfileService(bootstrapConfiguration, fixture.cluster.getZooKeeperConnectString());
                var owned = new SegmentProfileOwnedResources.Settings(requested, requiredRoot, root,
                        "/socket-initial",
                        ZooDefs.Ids.OPEN_ACL_UNSAFE, "ledger-profile", 4, Duration.ofSeconds(5),
                        Duration.ofMillis(100), 2, 4, 64);
                service = SegmentProfileService.withOwnedResources(bootstrapConfiguration,
                        new SecretKeySpec(bytes(32, 7), "AES"), VALIDATOR, owned, budget,
                        131072, 64, "socket-test", address, control.staticAuthorizer(),
                        control.exactAuthorizer(), read);
            } else {
                service = SegmentProfileService.fromConfiguration(bootstrapConfiguration,
                        new SecretKeySpec(bytes(32, 7), "AES"), VALIDATOR, startup, transport);
            }
        }

        IsolatedSegmentStorage storage() throws Exception {
            var field = SegmentProfileService.class.getDeclaredField("storage");
            field.setAccessible(true);
            return (IsolatedSegmentStorage) field.get(service);
        }

        void replaceNode(Fixture fixture, int target, boolean existing) throws Exception {
            replaceNode(fixture, target, existing, false);
        }

        org.apache.bookkeeper.server.EmbeddedServer assembleEmbedded() throws Exception {
            var classic = temporary.newFolder().toPath().resolve("classic-must-stay-absent");
            var configuration = new ServerConfiguration(bootstrapConfiguration)
                    .setMetadataServiceUri("do-not-open-classic://invalid")
                    .setJournalDirName(classic.resolve("journal").toString())
                    .setLedgerDirNames(new String[] {classic.resolve("ledger").toString()})
                    .setIndexDirName(new String[] {classic.resolve("index").toString()});
            var server = org.apache.bookkeeper.server.EmbeddedServer.builder(
                    new org.apache.bookkeeper.server.conf.BookieConfiguration(configuration))
                    .experimentalProfileService(service, false).build();
            assertFalse(Files.exists(classic));
            assertNull(server.getBookieService());
            assertNull(server.getRegistrationManager());
            assertNull(server.getLedgerManagerFactory());
            return server;
        }

        void replaceNode(Fixture fixture, int target, boolean existing, boolean useEmbedded) throws Exception {
            var previous = fixture.listeners.get(target);
            if (previous.isOpen()) {
                previous.close().sync();
            } else {
                previous.closeFuture().sync();
            }
            fixture.nodes.get(target).close();
            if (useEmbedded) {
                if (existing) {
                    var configuration = new ServerConfiguration(bootstrapConfiguration)
                            .setMetadataServiceUri("do-not-open-classic://invalid");
                    embedded = org.apache.bookkeeper.server.EmbeddedServer.builder(
                            new org.apache.bookkeeper.server.conf.BookieConfiguration(configuration))
                            .experimentalProfileService(service, true).build();
                } else {
                    embedded = assembleEmbedded();
                }
                embedded.getLifecycleComponentStack().start();
            } else {
                service.start(existing);
            }
            var field = SegmentProfileService.class.getDeclaredField("listener");
            field.setAccessible(true);
            var listenerField = SegmentProfileListener.class.getDeclaredField("listener");
            listenerField.setAccessible(true);
            fixture.listeners.set(target, (Channel) listenerField.get(field.get(service)));
            var bound = (InetSocketAddress) fixture.listeners.get(target).localAddress();
            fixture.nodes.set(target, storage());
            fixture.budgets.set(target, budget);
            if (ownsResources) {
                var factory = ownedTlsFactory(service);
                assertTrue(factory != fixture.serverTls);
                ownedTlsContext = tlsContext(factory);
                assertTrue(nativeTlsContext(ownedTlsContext).refCnt() > 0);
                var peer = persistent.readPeer(fixture.identities.get(target).bookieId().toString()).peer();
                assertNotNull(peer);
                assertEquals("tls://127.0.0.1:" + bound.getPort(), peer.projection().endpoint());
            } else {
                assertEquals("tls://127.0.0.1:" + bound.getPort(), publisher.readServiceInfo(
                        fixture.identities.get(target).bookieId().toString()).orElseThrow().endpoint());
                assertTrue(publisher.readWritable(fixture.identities.get(target).bookieId().toString()).isPresent());
            }
        }

        Object ownedField(String name) throws Exception {
            return ownedResourceField(service, name);
        }

        void assertOwnedResourcesTerminal(boolean terminal) throws Exception {
            assertEquals(terminal, ((EventLoopGroup) ownedField("worker")).isTerminated());
            assertEquals(terminal, ((EventLoopGroup) ownedField("acceptor")).isTerminated());
            assertEquals(terminal, ((ThreadPoolExecutor) ownedField("cold")).isTerminated());
            assertEquals(terminal, ((java.util.concurrent.ScheduledThreadPoolExecutor) ownedField("scheduler"))
                    .isTerminated());
            assertEquals(terminal, ownedField("zkClosed"));
            assertEquals(terminal, ownedField("managerClosed"));
            assertEquals(terminal, ownedField("driverClosed"));
            if (ownedTlsContext != null) {
                if (terminal) {
                    assertEquals(0, nativeTlsContext(ownedTlsContext).refCnt());
                } else {
                    assertTrue(nativeTlsContext(ownedTlsContext).refCnt() > 0);
                }
            }
        }

        @Override
        public void close() throws Exception {
            if (embedded != null) {
                embedded.getLifecycleComponentStack().close();
            }
            service.close();
            if (ownedTlsContext != null) {
                assertEquals(0, nativeTlsContext(ownedTlsContext).refCnt());
            }
            client.close();
        }
    }

    private static void configureOwnedProfileService(ServerConfiguration configuration, String connect)
            throws Exception {
        configuration.setMetadataServiceUri("zk+longhierarchical://" + connect + "/socket-ledgers");
        configuration.setZkTimeout(5000);
        configuration.setTLSProvider("OpenSSL");
        configuration.setTLSKeyStoreType("PEM");
        configuration.setTLSKeyStore(certificate("server-key.pem"));
        configuration.setTLSCertificatePath(certificate("server-san-cert.pem"));
        configuration.setTLSTrustStoreType("PEM");
        configuration.setTLSTrustStore(certificate("client-cert.pem"));
    }

    private static Map<String, Object> serviceSettings(IsolatedSegmentConfig config) {
        return Map.ofEntries(
                Map.entry("Mode", "ISOLATED"), Map.entry("Directory", config.directory().toString()),
                Map.entry("LogicalShards", config.logicalShards()), Map.entry("DataFiles", config.dataFiles()),
                Map.entry("BytesPerFile", config.bytesPerFile()),
                Map.entry("MaxPayloadBytes", config.maxPayloadBytes()),
                Map.entry("MaxPendingEntries", config.maxPendingEntries()), Map.entry("Workers", 1),
                Map.entry("IoThreads", 2), Map.entry("ControlSlots", 6), Map.entry("Buffers", 2),
                Map.entry("BufferBytes", 4096), Map.entry("InputBudgetBytes", 4096),
                Map.entry("BufferBudgetBytes", 2 * (4096L + 4095) + 4096), Map.entry("StartupTimeoutMillis", 5000),
                Map.entry("ControlLogBytes", ServiceEpisode.CONTROL_LOG_BYTES), Map.entry("HotEntries", 8),
                Map.entry("IndexedEntries", 16),
                Map.entry("PoolBlocks", 1), Map.entry("MaintenanceBlocks", 1), Map.entry("BatchBytes", 4096),
                Map.entry("BatchEntries", 1), Map.entry("BatchDelayMillis", 30000));
    }

    private static long serviceInputMetadataBytes(IsolatedSegmentConfig config) throws java.io.IOException {
        return SegmentEntryInputs.metadataCapacity(
                ((Number) serviceSettings(config).get("InputBudgetBytes")).longValue());
    }

    private static long serviceDriverMetadataBytes(IsolatedSegmentConfig config) throws java.io.IOException {
        var settings = serviceSettings(config);
        var execution = new SegmentExecutionGroup.Settings((Integer) settings.get("Workers"),
                (Integer) settings.get("IoThreads"), (Integer) settings.get("ControlSlots"),
                (Integer) settings.get("Buffers"), (Integer) settings.get("BufferBytes"),
                ((Number) settings.get("InputBudgetBytes")).longValue(),
                ((Number) settings.get("BufferBudgetBytes")).longValue(),
                Duration.ofMillis(((Number) settings.get("StartupTimeoutMillis")).longValue()));
        return SegmentDataPhysicalDriver.metadataCapacity(config, execution);
    }

    private static long serviceRestartHeadroom(IsolatedSegmentConfig config) throws java.io.IOException {
        var settings = serviceSettings(config);
        var execution = new SegmentExecutionGroup.Settings((Integer) settings.get("Workers"),
                (Integer) settings.get("IoThreads"), (Integer) settings.get("ControlSlots"),
                (Integer) settings.get("Buffers"), (Integer) settings.get("BufferBytes"),
                ((Number) settings.get("InputBudgetBytes")).longValue(),
                ((Number) settings.get("BufferBudgetBytes")).longValue(),
                Duration.ofMillis(((Number) settings.get("StartupTimeoutMillis")).longValue()));
        return SegmentControlCapacity.sum(SegmentPointRead.runtimeCapacity(config, execution),
                SegmentExecutionGroup.metadataCapacity(config, execution));
    }

    private static StartupReadinessInput servicePolicy(IsolatedSegmentConfig config, SegmentFileHeader identity,
            long generation) throws Exception {
        var policy = startupPolicy(config, identity);
        var device = policy.requiredDevices().devices().get(0);
        var devices = new RequiredDeviceManifest(policy.requiredDevices().identity(),
                policy.requiredDevices().generation(),
                List.of(new RequiredDeviceManifest.RequiredDeviceFact(device.deviceId(), device.storageIncarnation(),
                        device.manifestGeneration(), RequiredDeviceManifest.DeviceStatus.READY,
                        device.arenaFormatVersion(), device.controlFormatVersion(), device.checkpointFormatVersion(),
                        device.superblockGeneration(), device.mandatoryFeatures())));
        var f = policy.newScopeFallback();
        var arena = config.directory().getParent().toRealPath().resolve(config.directory().getFileName());
        var roots = f.newRoots().stream().map(root -> new NewScopeFallbackManifest.StorageRoot(root.kind(),
                switch (root.kind()) {
                    case ARENA -> arena.toString();
                    case INDEX -> arena.resolve("derived-index").toString();
                    default -> root.opaquePath();
                })).sorted(java.util.Comparator.comparing(NewScopeFallbackManifest.StorageRoot::opaquePath)).toList();
        var fallback = new NewScopeFallbackManifest(f.oldBookieId(), f.newBookieId(), f.oldStorageIncarnation(),
                f.newStorageIncarnation(), f.oldRoots(), roots, f.oldCredentialScope(), f.newCredentialScope(),
                f.oldScopeDisposition(), f.oldCredentialAccessToNewScope(), f.newCredentialAccessToNewScope());
        return new StartupReadinessInput(policy.compatibility(), devices, policy.recoveryFacts(), fallback,
                policy.rollbackSafetyFacts(), new Generation(generation), policy.capabilityGeneration(),
                policy.runtimeReaderVersion(), policy.runtimeWriterVersion(), policy.supportedMandatoryFeatures(),
                policy.profileEndpoint(), policy.capabilityHints());
    }

    @Test
    public void profileServiceDiskPreflightDoesNotCreateMissingRestartDirectory() throws Exception {
        try (Fixture fixture = new Fixture(false, false, true)) {
            var original = files(fixture.nodes.get(0)).config();
            var config = new IsolatedSegmentConfig(temporary.newFolder().toPath().resolve("missing-restart"),
                    1, 1, 1, original.bytesPerFile(), 4096, 1024, 16,
                    "FILE_CHANNEL", "OFF", "SYSTEM", "PARK");
            var policy = servicePolicy(config, fixture.identities.get(0), 1);
            try (var episode = new ServiceEpisode(fixture, 0, config, policy, policy.compatibility(),
                    new InetSocketAddress("127.0.0.1", 0), fixture.clientGroup)) {
                var configured = new ServerConfiguration(episode.bootstrapConfiguration)
                        .setDiskUsageThreshold(Math.nextDown(1f)).setDiskUsageWarnThreshold(Math.nextDown(1f));
                try (var guarded = SegmentProfileService.fromConfiguration(configured,
                        new SecretKeySpec(bytes(32, 7), "AES"), VALIDATOR, episode.startup, episode.transport)) {
                    assertThrows(java.io.IOException.class, () -> guarded.start(true));
                    assertFalse(Files.exists(config.directory()));
                    assertNull(episode.persistent.readPeer("socket0:3181").peer());
                    for (var lane : ProfileReceiveBudget.Lane.values()) {
                        assertEquals(0, episode.budget.used(lane));
                        assertEquals(0, episode.budget.usedConnections(lane));
                    }
                }
            }
        }
    }

    @Test
    public void everyProfileServiceAssemblyRejectsNativeCommonBindingBeforeStorageOpen() throws Exception {
        for (var phase : BookieRouteBinding.Phase.values()) {
            try (Fixture fixture = new Fixture(false, false, true)) {
                for (int assembly = 0; assembly < 3; assembly++) {
                    var config = new IsolatedSegmentConfig(temporary.newFolder().toPath().resolve("unopened"),
                            1, 1, 1, 4L * 1024 * 1024, 4096, 1024, 16,
                            "FILE_CHANNEL", "OFF", "SYSTEM", "PARK");
                    var identity = fixture.identities.get(assembly);
                    var requested = servicePolicy(config, identity, 1);
                    try (var episode = new ServiceEpisode(fixture, assembly, config, requested,
                            requested.compatibility(), new InetSocketAddress("127.0.0.1", 0), fixture.clientGroup,
                            false, assembly == 2)) {
                        // Real native metadata, separate from the experimental requirements namespace.
                        // This fixture tests refusal, not the future Classic replay/bootstrap issuer.
                        String root = "/socket-ledgers";
                        if (fixture.zk.exists(root + "/INSTANCEID", false) == null) {
                            fixture.zk.create(root + "/INSTANCEID", "startup-native-cluster".getBytes(
                                    StandardCharsets.UTF_8), ZooDefs.Ids.OPEN_ACL_UNSAFE, CreateMode.PERSISTENT);
                        }
                        String clusterId = new String(fixture.zk.getData(root + "/INSTANCEID", false, null),
                                StandardCharsets.UTF_8);
                        var source = new ServerConfiguration().setBookieId(identity.bookieId().toString())
                                .setJournalDirName("/disposable-old-journal")
                                .setLedgerDirNames(new String[]{"/disposable-old-ledger"});
                        var manager = new ZKRegistrationManager(source, fixture.zk, root);
                        var cookie = org.apache.bookkeeper.bookie.Cookie.generateCookie(source)
                                .setInstanceId(clusterId).build();
                        cookie.writeToRegistrationManager(manager, source,
                                org.apache.bookkeeper.versioning.Version.NEW);
                        var cookieStat = fixture.zk.exists(root + "/cookies/" + identity.bookieId(), false);
                        var binding = new BookieRouteBinding(clusterId,
                                fixture.zk.exists(root + "/INSTANCEID", false).getCzxid(), identity.bookieId(),
                                identity.incarnation(), UUID.randomUUID(),
                                requested.compatibility().deviceManifestIdentity(), config.directory().toString(),
                                new BookieRouteBinding.SourceCookie(cookieStat.getCzxid(), cookieStat.getVersion(),
                                        java.security.MessageDigest.getInstance("SHA-256").digest(
                                                cookie.toString().getBytes(StandardCharsets.UTF_8))),
                                BookieRouteBinding.Phase.PREPARED, java.util.Optional.empty());
                        var prepared = manager.prepareBookieRouteBinding(binding).observation().orElseThrow();
                        if (phase == BookieRouteBinding.Phase.ENABLED) {
                            assertEquals(BookieRouteBinding.WriteStatus.APPLIED,
                                    manager.completeBookieRouteBinding(prepared,
                                            new BookieRouteBinding.BootstrapSeal(UUID.randomUUID(), 0, -1)).status());
                        }
                        assertEquals(phase, manager.readBookieRouteBinding(identity.bookieId()).observation()
                                .orElseThrow().binding().phase());
                        assertNull(fixture.zk.exists("/socket-service-required-" + assembly + "-"
                                + Integer.toUnsignedString(config.directory().hashCode())
                                + "/bookie-route-bindings", false));
                        Exception failure;
                        if (assembly == 1) {
                            episode.embedded = episode.assembleEmbedded();
                            failure = assertThrows(Exception.class,
                                    () -> episode.embedded.getLifecycleComponentStack().start());
                        } else {
                            failure = assertThrows(IOException.class, () -> episode.service.start(false));
                        }
                        Throwable cause = failure;
                        while (cause.getCause() != null) {
                            cause = cause.getCause();
                        }
                        assertTrue(cause.toString(), cause.getMessage().contains(
                                "Independent Profile startup requires authoritative native absence: FOUND"));
                        assertFalse(Files.exists(config.directory()));
                        assertNull(episode.storage());
                        assertTrue(episode.persistent.read(identity.bookieId().toString())
                                .versionedRecord().isEmpty());
                        assertTrue(episode.service.close(Duration.ofSeconds(5)));
                        if (assembly == 2) {
                            episode.assertOwnedResourcesTerminal(true);
                        }
                        for (var lane : ProfileReceiveBudget.Lane.values()) {
                            assertEquals(0, episode.budget.used(lane));
                            assertEquals(0, episode.budget.usedConnections(lane));
                        }
                    }
                }
                assertFalse(fixture.worker.isShuttingDown());
                assertFalse(fixture.cold.isShutdown());
            }
        }
    }

    @Test
    public void nativeAbsenceCannotEraseCommonMarkersInActualProfileRoots() throws Exception {
        try (Fixture fixture = new Fixture(false, false, true)) {
            for (int placement = 0; placement < 5; placement++) {
                var config = new IsolatedSegmentConfig(temporary.newFolder().toPath().resolve("retained-marker"),
                        1, 1, 1, 4L * 1024 * 1024, 4096, 1024, 16,
                        "FILE_CHANNEL", "OFF", "SYSTEM", "PARK");
                var requested = servicePolicy(config, fixture.identities.get(0), 1);
                Path markerRoot = placement == 0 || placement == 3 ? config.directory() : placement == 1
                        ? config.directory().resolve("current") : SegmentDerivedIndex.directory(config);
                Files.createDirectories(markerRoot);
                Path marker = markerRoot.resolve(placement >= 3 ? ClassicRouteStartup.FRESH_LOCK_FILE_NAME
                        : SegmentClassicRootBindings.FILE_NAME);
                byte[] candidate = new byte[]{1, 2, 3};
                Files.write(marker, candidate);
                try (var episode = new ServiceEpisode(fixture, 0, config, requested, requested.compatibility(),
                        new InetSocketAddress("127.0.0.1", 0), fixture.clientGroup)) {
                    var failure = assertThrows(IOException.class, () -> episode.service.start(false));
                    assertTrue(failure.getMessage().contains(placement >= 3
                            ? "fresh Classic owner marker" : "retains a common binding"));
                    assertNull(episode.storage());
                    assertArrayEquals(candidate, Files.readAllBytes(marker));
                    try (var members = Files.list(config.directory())) {
                        assertEquals(1, members.count());
                    }
                    assertTrue(episode.persistent.read("socket0:3181").versionedRecord().isEmpty());
                }
            }
        }
    }

    @Test
    public void profileServiceHonorsFrozenDiskThresholdBeforeOpeningStorage() throws Exception {
        try (Fixture fixture = new Fixture(false, false, true)) {
            var parent = temporary.getRoot();
            float usage = 1f - (float) parent.getUsableSpace() / (float) parent.getTotalSpace();
            assertTrue(usage > 0);
            float limit = usage / 4;
            float high = Math.nextDown(1f);
            assertTrue(usage < high);
            var original = files(fixture.nodes.get(0)).config();
            for (boolean warnOnly : List.of(false, true)) {
                var config = new IsolatedSegmentConfig(temporary.newFolder().toPath().resolve("disk-check"),
                        1, 1, 1, original.bytesPerFile(), 4096, 1024, 16, "FILE_CHANNEL", "OFF", "SYSTEM", "PARK");
                var policy = servicePolicy(config, fixture.identities.get(0), 1);
                try (var episode = new ServiceEpisode(fixture, 0, config, policy, policy.compatibility(),
                        new InetSocketAddress("127.0.0.1", 0), fixture.clientGroup)) {
                    var configured = new ServerConfiguration(episode.bootstrapConfiguration)
                            .setDiskUsageThreshold(warnOnly ? high : limit).setDiskUsageWarnThreshold(limit / 2);
                    try (var guarded = SegmentProfileService.fromConfiguration(configured,
                            new SecretKeySpec(bytes(32, 7), "AES"), VALIDATOR, episode.startup, episode.transport)) {
                        // The caller's later configuration changes must not alter the admitted episode policy.
                        configured.setDiskUsageThreshold(warnOnly ? limit : high);
                        if (warnOnly) {
                            assertNotNull(guarded.start(false));
                            assertTrue(Files.isDirectory(config.directory()));
                            assertNotNull(episode.persistent.readPeer("socket0:3181").peer());
                        } else {
                            assertThrows(org.apache.bookkeeper.util.DiskChecker.DiskOutOfSpaceException.class,
                                    () -> guarded.start(false));
                            assertFalse(Files.exists(config.directory()));
                            assertNull(episode.persistent.readPeer("socket0:3181").peer());
                            for (var lane : ProfileReceiveBudget.Lane.values()) {
                                assertEquals(0, episode.budget.used(lane));
                                assertEquals(0, episode.budget.usedConnections(lane));
                            }
                        }
                    }
                }
            }
        }
    }

    @Test
    public void ownedProfileServiceRejectsRequirementsBeforeStorageOpenAndCleansBindFailure() throws Exception {
        try (Fixture fixture = new Fixture(false, false, true); BookKeeper sdk = sdk(fixture)) {
            for (int failure = 0; failure < 6; failure++) {
                var identity = fixture.identities.get(failure % 3);
                var config = new IsolatedSegmentConfig(temporary.newFolder().toPath().resolve("unopened"),
                        1, 1, 1, 4L * 1024 * 1024, 4096, 1024, 16, "FILE_CHANNEL", "OFF", "SYSTEM", "PARK");
                var requested = servicePolicy(config, identity, 1);
                var c = requested.compatibility();
                var required = failure == 0 ? null : new BookieCompatibilityFact(c.bookieId(), c.storageIncarnation(),
                        c.activeEngine(), c.profileWireMajor(), c.profileWireMinor(), c.descriptorHashSuite(),
                        c.mandatoryLocalFeatures(), c.deviceManifestIdentity(), c.deviceManifestGeneration(),
                        c.localFormatGeneration(), c.effectiveDeleteAssignmentGeneration(), failure == 2 ? 2 : 1,
                        c.minimumWriterVersion(), failure == 1 ? BookieCompatibilityFact.MigrationState.PREPARED
                                : BookieCompatibilityFact.MigrationState.FORMAT_READY, c.migrationGeneration());
                if (failure == 3 || failure == 5) {
                    var f = requested.newScopeFallback();
                    var roots = failure == 5 ? f.newRoots().stream().map(root -> root.kind()
                            == NewScopeFallbackManifest.RootKind.ARENA
                            ? new NewScopeFallbackManifest.StorageRoot(root.kind(), root.opaquePath() + "-other")
                            : root)
                            .sorted(java.util.Comparator.comparing(NewScopeFallbackManifest.StorageRoot::opaquePath))
                            .toList() : f.newRoots();
                    var unsafe = new NewScopeFallbackManifest(f.oldBookieId(), f.newBookieId(),
                            f.oldStorageIncarnation(), f.newStorageIncarnation(), f.oldRoots(), roots,
                            f.oldCredentialScope(), f.newCredentialScope(), failure == 3
                                    ? NewScopeFallbackManifest.OldScopeDisposition.UNKNOWN : f.oldScopeDisposition(),
                            f.oldCredentialAccessToNewScope(), f.newCredentialAccessToNewScope());
                    requested = new StartupReadinessInput(requested.compatibility(), requested.requiredDevices(),
                            requested.recoveryFacts(), unsafe, requested.rollbackSafetyFacts(),
                            requested.targetReadinessGeneration(), requested.capabilityGeneration(),
                            requested.runtimeReaderVersion(), requested.runtimeWriterVersion(),
                            requested.supportedMandatoryFeatures(), requested.profileEndpoint(),
                            requested.capabilityHints());
                }
                if (failure == 4) {
                    // Existing native endpoint: storage may open, but no readiness receipt may be published.
                    try (var episode = new ServiceEpisode(fixture, failure % 3, config, requested, required,
                            (InetSocketAddress) fixture.listeners.get(0).localAddress(),
                            sdk.getClientCtx().getScheduler())) {
                        assertThrows(java.io.IOException.class, () -> episode.service.start(false));
                        assertTrue(episode.service.close(Duration.ofSeconds(5)));
                        assertEquals(0, episode.budget.used(ProfileReceiveBudget.Lane.DATA));
                        assertEquals(0, episode.budget.used(ProfileReceiveBudget.Lane.CONTROL));
                        assertTrue(episode.budget.closeAdmissionAndDrain().isDone());
                        assertTrue(episode.persistent.read(identity.bookieId().toString()).versionedRecord().isEmpty());
                        try (var reopened = new IsolatedSegmentStorage(config, identity,
                                new SecretKeySpec(bytes(32, 7), "AES"), VALIDATOR,
                                new SegmentExecutionGroup.Settings(1, 2, 6, 2, 4096, 4096,
                                        2 * (4096L + 4095) + 4096, Duration.ofSeconds(5)),
                                new IsolatedSegmentStorage.Limits(1024 * 1024, 8, 16, 1, 1,
                                        new SegmentDataPhysicalDriver.BatchLimits(4096, 1, Duration.ofSeconds(30))))) {
                            reopened.restart();
                        }
                    }
                } else {
                    try (var episode = new ServiceEpisode(fixture, failure % 3, config, requested, required,
                            new InetSocketAddress("127.0.0.1", 0), sdk.getClientCtx().getScheduler())) {
                        assertThrows(java.io.IOException.class, () -> episode.service.start(false));
                        assertFalse(Files.exists(config.directory()));
                        assertNull(episode.storage());
                        assertTrue(episode.persistent.read(identity.bookieId().toString()).versionedRecord().isEmpty());
                    }
                }
            }
            assertFalse(fixture.worker.isShuttingDown());
            assertFalse(fixture.cold.isShutdown());
        }
    }

    @Test
    public void profileConfigurationRejectsInvalidBoundsBeforeOpenAndFreezesValidSettings() throws Exception {
        try (Fixture fixture = new Fixture(false, false, true); BookKeeper sdk = sdk(fixture)) {
            var config = new IsolatedSegmentConfig(temporary.newFolder().toPath().resolve("unopened"),
                    1, 1, 1, 4L * 1024 * 1024, 4096, 1024, 16, "FILE_CHANNEL", "OFF", "SYSTEM", "PARK");
            var requested = servicePolicy(config, fixture.identities.get(0), 1);
            try (var episode = new ServiceEpisode(fixture, 0, config, requested, requested.compatibility(),
                    new InetSocketAddress("127.0.0.1", 0), sdk.getClientCtx().getScheduler())) {
                for (var bad : Map.<String, Object>ofEntries(Map.entry("Buffers", 0), Map.entry("Workers", 2),
                        Map.entry("BufferBytes", 4096.5), Map.entry("InputBudgetBytes", 1),
                        Map.entry("BufferBudgetBytes", 4096), Map.entry("HotEntries", 0),
                        Map.entry("PoolBlocks", 1024), Map.entry("BatchBytes", 8192),
                        Map.entry("Backend", "IO_URING"), Map.entry("WaitStrategy", "BOUNDED_SPIN"),
                        Map.entry("Directory", "relative"), Map.entry("AdvancedRangeEnabled", true)).entrySet()) {
                    var invalid = new ServerConfiguration(episode.bootstrapConfiguration);
                    invalid.setProperty(SegmentProfileService.CONFIG_PREFIX + bad.getKey(), bad.getValue());
                    assertThrows(RuntimeException.class, () -> SegmentProfileService.fromConfiguration(invalid,
                            new SecretKeySpec(bytes(32, 7), "AES"), VALIDATOR, episode.startup, episode.transport));
                    assertFalse(Files.exists(config.directory()));
                }
                var missing = new ServerConfiguration(episode.bootstrapConfiguration);
                missing.clearProperty(SegmentProfileService.CONFIG_PREFIX + "IndexedEntries");
                assertThrows(IllegalArgumentException.class, () -> SegmentProfileService.fromConfiguration(missing,
                        new SecretKeySpec(bytes(32, 7), "AES"), VALIDATOR, episode.startup, episode.transport));
                assertNull(episode.storage());
                assertTrue(episode.persistent.read("socket0:3181").versionedRecord().isEmpty());
                // Mutating the original configuration cannot change the already frozen owner.
                episode.bootstrapConfiguration.setProperty(SegmentProfileService.CONFIG_PREFIX + "BufferBytes", 1);
                episode.bootstrapConfiguration.setProperty(SegmentProfileService.CONFIG_PREFIX + "Affinity", "REQUIRE");
                episode.replaceNode(fixture, 0, false, true);
                assertEquals("OFF", files(episode.storage()).config().affinity());
                assertEquals("SYSTEM", files(episode.storage()).config().numaPolicy());
                assertEquals("PARK", files(episode.storage()).config().waitStrategy());
            }
        }
    }

