    @Test
    public void physicalDeleteControlRechecksActualEventBeforeReportingReusable() throws Exception {
        try (Fixture fixture = new Fixture(false, false, true, 3, 2, true, true); BookKeeper sdk = sdk(fixture)) {
            var metadata = preparePhysicalDelete(fixture, sdk, false);
            var target = new org.apache.bookkeeper.discover.profile.ProfileDeleteRecord.Target(
                    "socket0:3181", fixture.identities.get(0).incarnation().value());
            var event = fixture.reservations.readLedgerDeleteDelivery(metadata, 44, target).event();
            var node = fixture.nodes.get(0);
            var field = IsolatedSegmentStorage.class.getDeclaredField("arena");
            field.setAccessible(true);
            var arena = (SegmentArenaControlLog) field.get(node);
            var ioField = SegmentArenaControlLog.class.getDeclaredField("io");
            ioField.setAccessible(true);
            var forcing = new CountDownLatch(1);
            var release = new CountDownLatch(1);
            ioField.set(arena, new SegmentFileIo(Integer.MAX_VALUE, -1, -1, false, () -> {
                forcing.countDown();
                await(release);
            }));
            try {
                var attempt = fixture.clients.get(target.bookie()).physicalDelete(
                        new ProfilePhysicalDeleteCodec.Request(event.deleteApply("ledger-profile"), 64, 8, 5000));
                assertTrue(forcing.await(5, TimeUnit.SECONDS));
                var children = fixture.zk.getChildren("/socket-initial/delete-delivery", false);
                String headName = "/socket-initial/delete-delivery/" + children.stream()
                        .filter(child -> !child.endsWith("-assignment"))
                        .filter(child -> {
                            try {
                                return org.apache.bookkeeper.discover.profile.ProfileDeleteDelivery.Head.decode(
                                        fixture.zk.getData("/socket-initial/delete-delivery/" + child, false, null))
                                            .target().equals(target);
                            } catch (Exception failure) {
                                throw new IllegalStateException(failure);
                            }
                        }).findFirst().orElseThrow();
                fixture.zk.delete(headName + "/event-1", 0);
                release.countDown();
                assertEquals(ProfilePhysicalDeleteCodec.Outcome.UNKNOWN,
                        attempt.result().get(10, TimeUnit.SECONDS).outcome());
                attempt.completion().get(5, TimeUnit.SECONDS);
                assertEquals(2, arena.allocationGeneration(0, 4096));
                assertTrue(bookie(node).hasAppliedDeleteEvent(event.deleteApply("ledger-profile")));
                assertEquals(ZKProfileReservationStore.DeliveryStatus.QUARANTINED,
                        fixture.reservations.readLedgerDeleteDelivery(metadata, 44, target).status());
                var manifest = fixture.reservations.readLogicalDeletion(metadata, 44, bytes(16, 101)).manifest();
                assertNotNull(manifest);
                var coordinator = new org.apache.bookkeeper.discover.profile.ProfileDeleteCoordinator(
                        fixture.reservations, metadata, fixture.cold);
                var checked = coordinator.beginObservePhysicalDeletion(manifest,
                        Map.of(target, fixture.clients.get(target.bookie())), sdk.getClientCtx(),
                        64, 8, Duration.ofSeconds(10));
                var result = checked.result().get(15, TimeUnit.SECONDS);
                checked.completion().get(5, TimeUnit.SECONDS);
                assertEquals(org.apache.bookkeeper.discover.profile.ProfileDeleteCoordinator.PhysicalStatus.QUARANTINED,
                        result.status());
                assertEquals(3, result.targets().size());
                assertEquals(ProfilePhysicalDeleteCodec.Outcome.UNKNOWN, result.targets().get(target).outcome());
            } finally {
                release.countDown();
            }
        }
    }

    @Test
    public void retentionWindowStartsAfterAllNativePhysicalReceiptsAndRestartsConservatively() throws Exception {
        try (Fixture fixture = new Fixture(false, false, true, 3, 2, true, true); BookKeeper sdk = sdk(fixture)) {
            var policy = new org.apache.bookkeeper.discover.profile.ProfileDeleteRetention.Policy(
                    1, UUID.randomUUID(), 500, 0, 500);
            assertEquals(ZKProfileReservationStore.CreateStatus.APPLIED,
                    fixture.reservations.publishDeleteRetentionPolicy(policy));
            var metadata = preparePhysicalDelete(fixture, sdk, false);
            var manifest = fixture.reservations.readLogicalDeletion(metadata, 44, bytes(16, 101)).manifest();
            var coordinator = new ProfileDeleteCoordinator(fixture.reservations, metadata, fixture.cold);
            var pending = coordinator.beginRetentionWindow(manifest, sdk.getClientCtx(), Duration.ofSeconds(5));
            assertEquals(ProfileDeleteCoordinator.RetentionWindowStatus.PENDING_TARGETS,
                    pending.result().get(5, TimeUnit.SECONDS).status());
            pending.completion().get(5, TimeUnit.SECONDS);
            var peers = new HashMap<ProfileDeleteRecord.Target, ProfileInitialControlClient>();
            for (var target : manifest.targets()) {
                var event = fixture.reservations.readLedgerDeleteDelivery(metadata, 44, target).event();
                var applied = fixture.clients.get(target.bookie()).deleteApply(event.deleteApply("ledger-profile"))
                        .get(5, TimeUnit.SECONDS).outcome();
                assertTrue(applied == ProfileControlResult.Outcome.APPLIED
                        || applied == ProfileControlResult.Outcome.ALREADY_APPLIED);
                peers.put(target, fixture.clients.get(target.bookie()));
            }
            var physical = coordinator.beginAwaitPhysicalDeletion(manifest, peers, sdk.getClientCtx(),
                    64, 8, Duration.ofSeconds(10));
            assertEquals(ProfileDeleteCoordinator.PhysicalStatus.DURABLY_REUSABLE_EVERY_TARGET,
                    physical.result().get(15, TimeUnit.SECONDS).status());
            physical.completion().get(5, TimeUnit.SECONDS);
            var begin = coordinator.beginRetentionWindow(manifest, sdk.getClientCtx(), Duration.ofSeconds(5));
            var waiting = begin.result().get(5, TimeUnit.SECONDS);
            begin.completion().get(5, TimeUnit.SECONDS);
            assertEquals(ProfileDeleteCoordinator.RetentionWindowStatus.WAITING, waiting.status());
            assertEquals(policy, waiting.window().barrier().retention().policy());
            assertTrue(waiting.window().nativeCommit() > waiting.window().barrier().latestTerminalCommit());
            String path = "/socket-initial/2c/delete-targets/retention-barrier";
            byte[] original = fixture.zk.getData(path, false, null);
            long until = System.nanoTime() + TimeUnit.SECONDS.toNanos(5);
            while (waiting.window().remainingMillis() != 0 && System.nanoTime() < until) {
                LockSupport.parkNanos(TimeUnit.MILLISECONDS.toNanos(10));
            }
            assertEquals(0, waiting.window().remainingMillis());
            var check = coordinator.beginCheckRetentionWindow(waiting.window(), sdk.getClientCtx(),
                    Duration.ofSeconds(5));
            assertEquals(ProfileDeleteCoordinator.RetentionWindowStatus.WINDOW_ELAPSED,
                    check.result().get(5, TimeUnit.SECONDS).status());
            check.completion().get(5, TimeUnit.SECONDS);
            var restarted = new ProfileDeleteCoordinator(fixture.reservations, metadata, fixture.cold);
            assertThrows(IllegalArgumentException.class, () -> restarted.beginCheckRetentionWindow(
                    waiting.window(), sdk.getClientCtx(), Duration.ofSeconds(5)));
            var fresh = restarted.beginRetentionWindow(manifest, sdk.getClientCtx(), Duration.ofSeconds(5));
            var freshWindow = fresh.result().get(5, TimeUnit.SECONDS);
            fresh.completion().get(5, TimeUnit.SECONDS);
            assertEquals(ProfileDeleteCoordinator.RetentionWindowStatus.WAITING, freshWindow.status());
            assertEquals(waiting.window().nativeCommit(), freshWindow.window().nativeCommit());
            assertArrayEquals(original, fixture.zk.getData(path, false, null));
            String guard = path + "/birth-" + waiting.window().barrier().birthId();
            byte[] guardBytes = fixture.zk.getData(guard, false, null);
            fixture.zk.delete(guard, 0);
            fixture.zk.create(guard, guardBytes, ZooDefs.Ids.OPEN_ACL_UNSAFE, CreateMode.PERSISTENT);
            var corrupt = restarted.beginCheckRetentionWindow(freshWindow.window(), sdk.getClientCtx(),
                    Duration.ofSeconds(5));
            assertEquals(ProfileDeleteCoordinator.RetentionWindowStatus.QUARANTINED,
                    corrupt.result().get(5, TimeUnit.SECONDS).status());
            corrupt.completion().get(5, TimeUnit.SECONDS);
            assertTrue(fixture.manager.readLedgerMetadata(44).get().getValue().getCustomMetadata()
                    .containsKey(ProfileDeleteRecord.TOMBSTONE_KEY));
        }
    }

    @Test
    public void retentionBarrierLostReplyCancelAndNativeGuardRaceKeepActualCustody() throws Exception {
        for (boolean hold : List.of(false, true)) {
            try (Fixture fixture = new Fixture(false, false, true, 3, 2, true, true); BookKeeper sdk = sdk(fixture)) {
                assertEquals(ZKProfileReservationStore.CreateStatus.APPLIED,
                        fixture.reservations.publishDeleteRetentionPolicy(
                                new org.apache.bookkeeper.discover.profile.ProfileDeleteRetention.Policy(
                                        1, UUID.randomUUID(), 60000, 0, 60000)));
                var metadata = preparePhysicalDelete(fixture, sdk, false);
                var manifest = fixture.reservations.readLogicalDeletion(metadata, 44, bytes(16, 101)).manifest();
                var peers = new HashMap<ProfileDeleteRecord.Target, ProfileInitialControlClient>();
                for (var target : manifest.targets()) {
                    var event = fixture.reservations.readLedgerDeleteDelivery(metadata, 44, target).event();
                    var applied = fixture.clients.get(target.bookie()).deleteApply(event.deleteApply("ledger-profile"))
                            .get(5, TimeUnit.SECONDS).outcome();
                    assertTrue(applied == ProfileControlResult.Outcome.APPLIED
                            || applied == ProfileControlResult.Outcome.ALREADY_APPLIED);
                    peers.put(target, fixture.clients.get(target.bookie()));
                }
                var physical = new ProfileDeleteCoordinator(fixture.reservations, metadata, fixture.cold)
                        .beginAwaitPhysicalDeletion(manifest, peers, sdk.getClientCtx(),
                                64, 8, Duration.ofSeconds(10));
                assertEquals(ProfileDeleteCoordinator.PhysicalStatus.DURABLY_REUSABLE_EVERY_TARGET,
                        physical.result().get(15, TimeUnit.SECONDS).status());
                physical.completion().get(5, TimeUnit.SECONDS);
                var watcher = new ZooKeeperWatcherBase(10000, false);
                try (var client = new HandoffReplyClient(fixture.cluster.getZooKeeperConnectString(), watcher,
                        hold, "/retention-barrier")) {
                    var source = new ZKProfileReservationStore(client, "/socket-initial",
                            ZooDefs.Ids.OPEN_ACL_UNSAFE, Duration.ofSeconds(5));
                    var scoped = new ProfileLedgerMetadataStore(client, (AbstractZkLedgerManager) fixture.manager,
                            ZooDefs.Ids.OPEN_ACL_UNSAFE, Duration.ofSeconds(5));
                    var coordinator = new ProfileDeleteCoordinator(source, scoped, fixture.cold);
                    var attempt = coordinator.beginRetentionWindow(manifest, sdk.getClientCtx(),
                            Duration.ofSeconds(10));
                    assertTrue(client.committed.await(5, TimeUnit.SECONDS));
                    String path = "/socket-initial/2c/delete-targets/retention-barrier";
                    byte[] original = fixture.zk.getData(path, false, null);
                    if (hold) {
                        assertTrue(attempt.result().cancel(false));
                        assertFalse(attempt.completion().isDone());
                        attempt.completion().complete(null);
                        var busy = coordinator.beginRetentionWindow(manifest, sdk.getClientCtx(),
                                Duration.ofSeconds(5));
                        assertEquals(ProfileDeleteCoordinator.RetentionWindowStatus.UNAVAILABLE,
                                busy.result().get(5, TimeUnit.SECONDS).status());
                        client.release.run();
                    } else {
                        assertEquals(ProfileDeleteCoordinator.RetentionWindowStatus.WAITING,
                                attempt.result().get(5, TimeUnit.SECONDS).status());
                        attempt.completion().get(5, TimeUnit.SECONDS);
                    }
                    ProfileDeleteCoordinator.RetentionWindowResult resolved = null;
                    long until = System.nanoTime() + TimeUnit.SECONDS.toNanos(5);
                    do {
                        var resumed = coordinator.beginRetentionWindow(manifest, sdk.getClientCtx(),
                                Duration.ofSeconds(5));
                        resolved = resumed.result().get(5, TimeUnit.SECONDS);
                        resumed.completion().get(5, TimeUnit.SECONDS);
                        if (resolved.status() == ProfileDeleteCoordinator.RetentionWindowStatus.UNAVAILABLE) {
                            LockSupport.parkNanos(TimeUnit.MILLISECONDS.toNanos(10));
                        }
                    } while (resolved.status() == ProfileDeleteCoordinator.RetentionWindowStatus.UNAVAILABLE
                            && System.nanoTime() < until);
                    assertEquals(ProfileDeleteCoordinator.RetentionWindowStatus.WAITING, resolved.status());
                    assertArrayEquals(original, resolved.window().barrier().encode());
                    assertArrayEquals(original, fixture.zk.getData(path, false, null));
                    assertTrue(resolved.window().remainingMillis() > 0);
                }
                // A selected native guard removal must reject the entire barrier transaction.
                String path = "/socket-initial/2c/delete-targets/retention-barrier";
                var first = fixture.reservations.readDeleteRetentionBarrier(metadata, manifest);
                fixture.zk.delete(path + "/birth-" + first.barrier().birthId(), 0);
                fixture.zk.delete(path, 0);
                var receipt = fixture.reservations.readPhysicalDeleteReceipt(metadata, manifest,
                        manifest.targets().get(0)).receipt();
                String guard = physicalReceiptPath(fixture, receipt) + "/birth-"
                        + java.util.HexFormat.of().formatHex(receipt.birthId());
                var raceWatcher = new ZooKeeperWatcherBase(10000, false);
                try (var client = new HandoffReplyClient(fixture.cluster.getZooKeeperConnectString(), raceWatcher,
                        false, "/retention-barrier")) {
                    client.beforeSelectedMulti = () -> {
                        try {
                            fixture.zk.delete(guard, 0);
                        } catch (Exception failure) {
                            throw new IllegalStateException(failure);
                        }
                    };
                    var source = new ZKProfileReservationStore(client, "/socket-initial",
                            ZooDefs.Ids.OPEN_ACL_UNSAFE, Duration.ofSeconds(5));
                    var scoped = new ProfileLedgerMetadataStore(client, (AbstractZkLedgerManager) fixture.manager,
                            ZooDefs.Ids.OPEN_ACL_UNSAFE, Duration.ofSeconds(5));
                    var attempt = new ProfileDeleteCoordinator(source, scoped, fixture.cold)
                            .beginRetentionWindow(manifest, sdk.getClientCtx(), Duration.ofSeconds(5));
                    assertEquals(ProfileDeleteCoordinator.RetentionWindowStatus.QUARANTINED,
                            attempt.result().get(5, TimeUnit.SECONDS).status());
                    attempt.completion().get(5, TimeUnit.SECONDS);
                    assertNull(client.beforeSelectedMulti);
                    assertNull(fixture.zk.exists(path, false));
                    assertTrue(fixture.manager.readLedgerMetadata(44).get().getValue().getCustomMetadata()
                            .containsKey(ProfileDeleteRecord.TOMBSTONE_KEY));
                }
            }
        }
    }

    private String physicalReceiptPath(Fixture fixture, ProfileDeletePhysicalReceipt receipt) throws Exception {
        String parent = "/socket-initial/2c/delete-targets";
        String marker = "birth-" + java.util.HexFormat.of().formatHex(receipt.birthId());
        for (String child : fixture.zk.getChildren(parent, false)) {
            if (child.startsWith("physical-") && fixture.zk.getChildren(parent + "/" + child, false).contains(marker)) {
                return parent + "/" + child;
            }
        }
        throw new AssertionError("Actual immutable physical receipt is missing");
    }

    @Test
    public void physicalDeletionReceiptsResumeAcrossCoordinatorRestartAndActualOfflineTargets() throws Exception {
        try (Fixture fixture = new Fixture(false, false, true, 3, 2, true, true); BookKeeper sdk = sdk(fixture)) {
            var metadata = preparePhysicalDelete(fixture, sdk, false);
            var manifest = fixture.reservations.readLogicalDeletion(metadata, 44, bytes(16, 101)).manifest();
            var first = manifest.targets().get(0);
            for (var target : manifest.targets()) {
                var event = fixture.reservations.readLedgerDeleteDelivery(metadata, 44, target).event();
                var applied = fixture.clients.get(target.bookie()).deleteApply(event.deleteApply("ledger-profile"))
                        .get(5, TimeUnit.SECONDS);
                assertTrue(applied.outcome() == Outcome.APPLIED || applied.outcome() == Outcome.ALREADY_APPLIED);
            }
            var coordinator = new ProfileDeleteCoordinator(fixture.reservations, metadata, fixture.cold);
            var partial = coordinator.beginAwaitPhysicalDeletion(manifest,
                    Map.of(first, fixture.clients.get(first.bookie())), sdk.getClientCtx(),
                    64, 8, Duration.ofSeconds(10));
            var partialResult = partial.result().get(15, TimeUnit.SECONDS);
            partial.completion().get(5, TimeUnit.SECONDS);
            assertEquals(ProfileDeleteCoordinator.PhysicalStatus.PENDING, partialResult.status());
            assertEquals(3, partialResult.targets().size());
            var stored = fixture.reservations.readPhysicalDeleteReceipt(metadata, manifest, first);
            assertEquals(ZKProfileReservationStore.PhysicalReceiptStatus.FOUND, stored.status());
            byte[] original = stored.receipt().encode();
            assertEquals(ProfilePhysicalDeleteCodec.Outcome.REUSABLE, stored.receipt().reply().outcome());
            var others = new HashMap<ProfileDeleteRecord.Target, ProfileInitialControlClient>();
            for (int index = 0; index < 3; index++) {
                var target = manifest.targets().get(index);
                if (target.equals(first)) {
                    fixture.clients.get(target.bookie()).closeAsync().get(5, TimeUnit.SECONDS);
                    fixture.listeners.get(index).close().sync();
                    fixture.nodes.get(index).close();
                } else {
                    others.put(target, fixture.clients.get(target.bookie()));
                    assertEquals(ZKProfileReservationStore.PhysicalReceiptStatus.ABSENT,
                            fixture.reservations.readPhysicalDeleteReceipt(metadata, manifest, target).status());
                }
            }
            var freshStore = new ZKProfileReservationStore(fixture.zk, "/socket-initial",
                    ZooDefs.Ids.OPEN_ACL_UNSAFE, Duration.ofSeconds(5));
            var fresh = new ProfileDeleteCoordinator(freshStore, metadata, fixture.cold);
            var remaining = fresh.beginAwaitPhysicalDeletion(manifest, others, sdk.getClientCtx(),
                    64, 8, Duration.ofSeconds(10));
            assertEquals(ProfileDeleteCoordinator.PhysicalStatus.DURABLY_REUSABLE_EVERY_TARGET,
                    remaining.result().get(15, TimeUnit.SECONDS).status());
            remaining.completion().get(5, TimeUnit.SECONDS);
            for (int index = 1; index < 3; index++) {
                fixture.clients.get(manifest.targets().get(index).bookie()).closeAsync().get(5, TimeUnit.SECONDS);
                fixture.listeners.get(index).close().sync();
                fixture.nodes.get(index).close();
            }
            var offline = new ProfileDeleteCoordinator(freshStore, metadata, fixture.cold)
                    .beginAwaitPhysicalDeletion(manifest, Map.of(), sdk.getClientCtx(),
                            64, 8, Duration.ofSeconds(10));
            assertEquals(ProfileDeleteCoordinator.PhysicalStatus.DURABLY_REUSABLE_EVERY_TARGET,
                    offline.result().get(15, TimeUnit.SECONDS).status());
            offline.completion().get(5, TimeUnit.SECONDS);
            assertArrayEquals(original,
                    freshStore.readPhysicalDeleteReceipt(metadata, manifest, first).receipt().encode());
            assertEquals(3, freshStore.retainedActivationTargets(44).targets().size());
            assertTrue(fixture.manager.readLedgerMetadata(44).get().getValue().getCustomMetadata()
                    .containsKey(ProfileDeleteRecord.TOMBSTONE_KEY));
            var wrong = new ProfileDeleteRecord.Target(first.bookie(), bytes(16, 93));
            assertEquals(ZKProfileReservationStore.PhysicalReceiptStatus.QUARANTINED,
                    freshStore.readPhysicalDeleteReceipt(metadata, manifest, wrong).status());
        }
    }

    @Test
    public void physicalDeletionReceiptRejectsMissingGuardAndRecreatedMetadataBirth() throws Exception {
        for (boolean metadataAba : List.of(false, true)) {
            try (Fixture fixture = new Fixture(false, false, true, 3, 2, true, true); BookKeeper sdk = sdk(fixture)) {
                var metadata = preparePhysicalDelete(fixture, sdk, false);
                var manifest = fixture.reservations.readLogicalDeletion(metadata, 44, bytes(16, 101)).manifest();
                var target = manifest.targets().get(0);
                var attempt = new ProfileDeleteCoordinator(fixture.reservations, metadata, fixture.cold)
                        .beginAwaitPhysicalDeletion(manifest, Map.of(target, fixture.clients.get(target.bookie())),
                                sdk.getClientCtx(), 64, 8, Duration.ofSeconds(10));
                assertEquals(ProfileDeleteCoordinator.PhysicalStatus.PENDING,
                        attempt.result().get(15, TimeUnit.SECONDS).status());
                attempt.completion().get(5, TimeUnit.SECONDS);
                var receipt = fixture.reservations.readPhysicalDeleteReceipt(metadata, manifest, target).receipt();
                assertNotNull(receipt);
                if (metadataAba) {
                    String path = ((AbstractZkLedgerManager) fixture.manager).getLedgerPath(44);
                    var before = new org.apache.zookeeper.data.Stat();
                    byte[] body = fixture.zk.getData(path, false, before);
                    var guards = new java.util.TreeMap<String, byte[]>();
                    for (String child : fixture.zk.getChildren(path, false)) {
                        assertTrue(fixture.zk.getChildren(path + "/" + child, false).isEmpty());
                        guards.put(child, fixture.zk.getData(path + "/" + child, false, null));
                    }
                    org.apache.zookeeper.ZKUtil.deleteRecursive(fixture.zk, path);
                    fixture.zk.create(path, body, ZooDefs.Ids.OPEN_ACL_UNSAFE, CreateMode.PERSISTENT);
                    for (var guard : guards.entrySet()) {
                        fixture.zk.create(path + "/" + guard.getKey(), guard.getValue(),
                                ZooDefs.Ids.OPEN_ACL_UNSAFE, CreateMode.PERSISTENT);
                    }
                    for (int version = 0; version < before.getVersion(); version++) {
                        fixture.zk.setData(path, body, -1);
                    }
                    var after = new org.apache.zookeeper.data.Stat();
                    assertArrayEquals(body, fixture.zk.getData(path, false, after));
                    assertEquals(before.getVersion(), after.getVersion());
                    assertNotEquals(before.getCzxid(), after.getCzxid());
                } else {
                    String path = physicalReceiptPath(fixture, receipt) + "/birth-"
                            + java.util.HexFormat.of().formatHex(receipt.birthId());
                    byte[] body = fixture.zk.getData(path, false, null);
                    fixture.zk.delete(path, 0);
                    assertEquals(ZKProfileReservationStore.PhysicalReceiptStatus.QUARANTINED,
                            fixture.reservations.readPhysicalDeleteReceipt(metadata, manifest, target).status());
                    fixture.zk.create(path, body, ZooDefs.Ids.OPEN_ACL_UNSAFE, CreateMode.PERSISTENT);
                }
                assertEquals(ZKProfileReservationStore.PhysicalReceiptStatus.QUARANTINED,
                        fixture.reservations.readPhysicalDeleteReceipt(metadata, manifest, target).status());
                var fresh = new ProfileDeleteCoordinator(fixture.reservations, metadata, fixture.cold)
                        .beginAwaitPhysicalDeletion(manifest, Map.of(), sdk.getClientCtx(),
                                64, 8, Duration.ofSeconds(10));
                var result = fresh.result().get(15, TimeUnit.SECONDS);
                fresh.completion().get(5, TimeUnit.SECONDS);
                assertEquals(ProfileDeleteCoordinator.PhysicalStatus.QUARANTINED, result.status());
                assertEquals(3, result.targets().size());
            }
        }
    }

    private static final class PhysicalReceiptReplyClient extends ZooKeeper {
        private final boolean hold;
        final CountDownLatch committed = new CountDownLatch(1);
        volatile boolean intercepted;
        volatile Runnable release;
        volatile CountDownLatch resumeSubmission;

        PhysicalReceiptReplyClient(String connect, ZooKeeperWatcherBase watcher, boolean hold) throws Exception {
            super(connect, 10000, watcher);
            this.hold = hold;
            watcher.waitForConnection();
        }

        @Override
        public void multi(Iterable<org.apache.zookeeper.Op> operations,
                org.apache.zookeeper.AsyncCallback.MultiCallback callback, Object context) {
            var ops = new ArrayList<org.apache.zookeeper.Op>();
            operations.forEach(ops::add);
            boolean physical = !intercepted && ops.stream().anyMatch(op ->
                    op.getType() == ZooDefs.OpCode.create && op.getPath().contains("/delete-targets/physical-"));
            super.multi(ops, (code, path, ignored, results) -> {
                if (physical && code == org.apache.zookeeper.KeeperException.Code.OK.intValue()) {
                    intercepted = true;
                    if (hold) {
                        release = () -> callback.processResult(code, path, context, results);
                    } else {
                        callback.processResult(org.apache.zookeeper.KeeperException.Code.CONNECTIONLOSS.intValue(),
                                path, context, results);
                    }
                    committed.countDown();
                } else {
                    callback.processResult(code, path, context, results);
                }
            }, context);
            var resume = resumeSubmission;
            if (physical && resume != null) {
                // Pause the submitting thread even though ZooKeeper has already returned its actual callback.
                await(resume);
            }
        }
    }

    @Test
    public void physicalDeletionReceiptLostReplyAndCallerCancelResolveSameNativeCommit() throws Exception {
        for (boolean cancel : List.of(false, true)) {
            try (Fixture fixture = new Fixture(false, false, true, 3, 2, true, true); BookKeeper sdk = sdk(fixture)) {
                var metadata = preparePhysicalDelete(fixture, sdk, false);
                var manifest = fixture.reservations.readLogicalDeletion(metadata, 44, bytes(16, 101)).manifest();
                var target = manifest.targets().get(0);
                var watcher = new ZooKeeperWatcherBase(10000, false);
                try (var client = new PhysicalReceiptReplyClient(fixture.cluster.getZooKeeperConnectString(),
                        watcher, cancel)) {
                    var store = new ZKProfileReservationStore(client, "/socket-initial",
                            ZooDefs.Ids.OPEN_ACL_UNSAFE, Duration.ofSeconds(5));
                    var borrowedMetadata = new ProfileLedgerMetadataStore(client,
                            (AbstractZkLedgerManager) fixture.manager, ZooDefs.Ids.OPEN_ACL_UNSAFE,
                            Duration.ofSeconds(5));
                    var coordinator = new ProfileDeleteCoordinator(store, borrowedMetadata, fixture.cold);
                    var attempt = coordinator.beginAwaitPhysicalDeletion(manifest,
                            Map.of(target, fixture.clients.get(target.bookie())), sdk.getClientCtx(),
                            64, 8, Duration.ofSeconds(10));
                    try {
                        assertTrue(client.committed.await(5, TimeUnit.SECONDS));
                        if (cancel) {
                            assertTrue(attempt.result().cancel(false));
                            assertThrows(java.util.concurrent.TimeoutException.class,
                                    () -> attempt.completion().get(150, TimeUnit.MILLISECONDS));
                            Runnable released = client.release;
                            client.release = null;
                            released.run();
                        } else {
                            assertEquals(ProfileDeleteCoordinator.PhysicalStatus.PENDING,
                                    attempt.result().get(15, TimeUnit.SECONDS).status());
                        }
                        attempt.completion().get(5, TimeUnit.SECONDS);
                        assertTrue(client.intercepted);
                        var durable = store.readPhysicalDeleteReceipt(borrowedMetadata, manifest, target);
                        assertEquals(ZKProfileReservationStore.PhysicalReceiptStatus.FOUND, durable.status());
                        byte[] original = durable.receipt().encode();
                        var resumed = new ProfileDeleteCoordinator(store, borrowedMetadata, fixture.cold)
                                .beginAwaitPhysicalDeletion(manifest, Map.of(), sdk.getClientCtx(),
                                        64, 8, Duration.ofSeconds(10));
                        var result = resumed.result().get(15, TimeUnit.SECONDS);
                        resumed.completion().get(5, TimeUnit.SECONDS);
                        assertEquals(ProfileDeleteCoordinator.PhysicalStatus.PENDING, result.status());
                        assertEquals(ProfilePhysicalDeleteCodec.Outcome.REUSABLE,
                                result.targets().get(target).outcome());
                        assertArrayEquals(original,
                                store.readPhysicalDeleteReceipt(borrowedMetadata, manifest, target).receipt().encode());
                        assertEquals(1, fixture.zk.getChildren("/socket-initial/2c/delete-targets", false).stream()
                                .filter(child -> child.startsWith("physical-")).count());
                    } finally {
                        if (client.release != null) {
                            client.release.run();
                        }
                    }
                }
            }
        }
    }

    @Test
    public void physicalDeletionReceiptReadbackKeepsTheOriginalStoreDeadline() throws Exception {
        try (Fixture fixture = new Fixture(false, false, true, 3, 2, true, true); BookKeeper sdk = sdk(fixture)) {
            var metadata = preparePhysicalDelete(fixture, sdk, false);
            var manifest = fixture.reservations.readLogicalDeletion(metadata, 44, bytes(16, 101)).manifest();
            var target = manifest.targets().get(0);
            var watcher = new ZooKeeperWatcherBase(10000, false);
            try (var client = new PhysicalReceiptReplyClient(fixture.cluster.getZooKeeperConnectString(),
                    watcher, true)) {
                var resume = new CountDownLatch(1);
                client.resumeSubmission = resume;
                var timeout = Duration.ofSeconds(2);
                var store = new ZKProfileReservationStore(client, "/socket-initial",
                        ZooDefs.Ids.OPEN_ACL_UNSAFE, timeout);
                var scoped = new ProfileLedgerMetadataStore(client, (AbstractZkLedgerManager) fixture.manager,
                        ZooDefs.Ids.OPEN_ACL_UNSAFE, timeout);
                var attempt = new ProfileDeleteCoordinator(store, scoped, fixture.cold)
                        .beginAwaitPhysicalDeletion(manifest, Map.of(target, fixture.clients.get(target.bookie())),
                                sdk.getClientCtx(), 64, 8, Duration.ofSeconds(15));
                ProfileDeletePhysicalReceipt original;
                try {
                    assertTrue(client.committed.await(5, TimeUnit.SECONDS));
                    client.release.run();
                    client.release = null;
                    var durable = fixture.reservations.readPhysicalDeleteReceipt(metadata, manifest, target);
                    assertEquals(ZKProfileReservationStore.PhysicalReceiptStatus.FOUND, durable.status());
                    original = durable.receipt();
                    assertThrows(java.util.concurrent.TimeoutException.class,
                            () -> attempt.result().get(timeout.plusMillis(100).toMillis(), TimeUnit.MILLISECONDS));
                    assertFalse(attempt.completion().isDone());
                } finally {
                    if (client.release != null) {
                        client.release.run();
                    }
                    resume.countDown();
                }
                var expired = attempt.result().get(5, TimeUnit.SECONDS);
                attempt.completion().get(5, TimeUnit.SECONDS);
                assertEquals(ProfileDeleteCoordinator.PhysicalStatus.PENDING, expired.status());
                assertEquals(ProfilePhysicalDeleteCodec.Outcome.UNKNOWN, expired.targets().get(target).outcome());

                String row = physicalReceiptPath(fixture, original);
                long birth = fixture.zk.exists(row, false).getCzxid();
                var replay = new ProfileDeleteCoordinator(store, scoped, fixture.cold)
                        .beginAwaitPhysicalDeletion(manifest, Map.of(), sdk.getClientCtx(),
                                64, 8, Duration.ofSeconds(10));
                var resolved = replay.result().get(5, TimeUnit.SECONDS);
                replay.completion().get(5, TimeUnit.SECONDS);
                assertEquals(ProfilePhysicalDeleteCodec.Outcome.REUSABLE, resolved.targets().get(target).outcome());
                assertEquals(birth, fixture.zk.exists(row, false).getCzxid());
                assertArrayEquals(original.encode(), store.readPhysicalDeleteReceipt(scoped, manifest, target)
                        .receipt().encode());
            }
        }
    }

    @Test
    public void physicalDeletionReceiptNeverPersistsPendingBeforeActualFree() throws Exception {
        try (Fixture fixture = new Fixture(false, false, true, 3, 2, true, true); BookKeeper sdk = sdk(fixture)) {
            var metadata = preparePhysicalDelete(fixture, sdk, false);
            var manifest = fixture.reservations.readLogicalDeletion(metadata, 44, bytes(16, 101)).manifest();
            var target = manifest.targets().get(0);
            var node = fixture.nodes.get(0);
            var field = IsolatedSegmentStorage.class.getDeclaredField("arena");
            field.setAccessible(true);
            var arena = (SegmentArenaControlLog) field.get(node);
            var ioField = SegmentArenaControlLog.class.getDeclaredField("io");
            ioField.setAccessible(true);
            var forcing = new CountDownLatch(1);
            var release = new CountDownLatch(1);
            ioField.set(arena, new SegmentFileIo(Integer.MAX_VALUE, -1, -1, false, () -> {
                forcing.countDown();
                await(release);
            }));
            var coordinator = new ProfileDeleteCoordinator(fixture.reservations, metadata, fixture.cold);
            try {
                var attempt = coordinator.beginAwaitPhysicalDeletion(manifest,
                        Map.of(target, fixture.clients.get(target.bookie())), sdk.getClientCtx(),
                        64, 8, Duration.ofMillis(400));
                assertTrue(forcing.await(5, TimeUnit.SECONDS));
                assertEquals(ProfileDeleteCoordinator.PhysicalStatus.PENDING,
                        attempt.result().get(5, TimeUnit.SECONDS).status());
                attempt.completion().get(5, TimeUnit.SECONDS);
                assertEquals(ZKProfileReservationStore.PhysicalReceiptStatus.ABSENT,
                        fixture.reservations.readPhysicalDeleteReceipt(metadata, manifest, target).status());
                assertThrows(java.io.IOException.class, () -> files(node).close());
                release.countDown();
                boolean stored = false;
                for (int tries = 0; tries < 50 && !stored; tries++) {
                    var resumed = coordinator.beginAwaitPhysicalDeletion(manifest,
                            Map.of(target, fixture.clients.get(target.bookie())), sdk.getClientCtx(),
                            64, 8, Duration.ofSeconds(5));
                    resumed.result().get(10, TimeUnit.SECONDS);
                    resumed.completion().get(5, TimeUnit.SECONDS);
                    stored = fixture.reservations.readPhysicalDeleteReceipt(metadata, manifest, target).status()
                            == ZKProfileReservationStore.PhysicalReceiptStatus.FOUND;
                    if (!stored) {
                        LockSupport.parkNanos(TimeUnit.MILLISECONDS.toNanos(10));
                    }
                }
                assertTrue(stored);
                assertEquals(2, arena.allocationGeneration(0, 4096));
            } finally {
                release.countDown();
            }
        }
    }

    @Test
    public void physicalDeleteReclaimsSocketDataAndEmptyLedgerWithoutDroppingOtherTargetsOrShrinkingFiles()
            throws Exception {
        for (boolean empty : List.of(false, true)) {
            try (Fixture fixture = new Fixture(false, false, true, 3, 2, true, true); BookKeeper sdk = sdk(fixture)) {
                preparePhysicalDelete(fixture, sdk, empty);
                var node = fixture.nodes.get(0);
                var wrong = new org.apache.bookkeeper.common.profile.wire.ProfileLedgerContext(44,
                        bytes(16, 98), fixture.context().descriptorIdentity());
                assertEquals(SegmentProfilePhysicalDelete.Status.NOT_DELETED,
                        node.reclaimDeletedLedger(wrong, fixture.cold, 64, 8, Duration.ofSeconds(5)).result().get()
                            .status());
                assertEquals(SegmentProfilePhysicalDelete.Status.NOT_DELETED,
                        fixture.nodes.get(1).reclaimDeletedLedger(fixture.context(), fixture.cold, 64, 8,
                                Duration.ofSeconds(5)).result().get().status());
                var attempt = node.reclaimDeletedLedger(fixture.context(), fixture.cold, 64, 8,
                        Duration.ofSeconds(10));
                var result = attempt.result().get(10, TimeUnit.SECONDS);
                attempt.completion().get(5, TimeUnit.SECONDS);
                assertEquals(SegmentProfilePhysicalDelete.Status.REUSABLE, result.status());
                assertEquals(empty ? 0 : 1, result.compactions());
                assertEquals(empty ? 0 : 1, result.freedAllocations());
                assertEquals(empty ? 0 : SegmentArenaControlLog.BLOCK_BYTES, result.sourceBytesRetired());
                assertEquals(0, result.destinationBytes());
                assertTrue(result.bookieCut() > 0);
                assertTrue(result.arenaCut() >= 0);
                assertEquals(3, fixture.reservations.retainedActivationTargets(44).targets().size());
                assertTrue(fixture.manager.readLedgerMetadata(44).get().getValue().getCustomMetadata()
                        .containsKey(org.apache.bookkeeper.discover.profile.ProfileDeleteRecord.TOMBSTONE_KEY));
                var again = node.reclaimDeletedLedger(fixture.context(), fixture.cold, 64, 8,
                        Duration.ofSeconds(5));
                assertEquals(0, again.result().get().compactions());
                again.completion().get(5, TimeUnit.SECONDS);
                var config = files(node).config();
                assertEquals(config.bytesPerFile(), Files.size(config.directory().resolve("data-0")));
                node.close();
                try (var replay = new IsolatedSegmentStorage(config, fixture.identities.get(0),
                        new SecretKeySpec(bytes(32, 7), "AES"), VALIDATOR,
                        new SegmentExecutionGroup.Settings(1, 2, 6, 2, 4096, 4096,
                                2 * (4096L + 4095) + 4096, Duration.ofSeconds(5)),
                        new IsolatedSegmentStorage.Limits(1024 * 1024, 8, 16, 1, 1,
                                new SegmentDataPhysicalDriver.BatchLimits(4096, 1, Duration.ofSeconds(30))))) {
                    replay.restart();
                    var verified = replay.reclaimDeletedLedger(fixture.context(), fixture.cold, 64, 8,
                            Duration.ofSeconds(5));
                    assertEquals(SegmentProfilePhysicalDelete.Status.REUSABLE, verified.result().get().status());
                    verified.completion().get(5, TimeUnit.SECONDS);
                    assertTrue(bookie(replay).hasTerminalTombstone(fixture.context()));
                    assertFalse(replay.profileReadVisible(fixture.context(), 0));
                    assertEquals(config.bytesPerFile(), Files.size(config.directory().resolve("data-0")));
                }
            }
        }
    }

    @Test
    public void physicalDeleteQueuedColdDeadlineReturnsPendingWhileActualWorkAndSingletonRemainHeld()
            throws Exception {
        try (Fixture fixture = new Fixture(false, false, true, 3, 2, true, true); BookKeeper sdk = sdk(fixture)) {
            preparePhysicalDelete(fixture, sdk, false);
            var cold = new ThreadPoolExecutor(1, 1, 0, TimeUnit.MILLISECONDS, new ArrayBlockingQueue<>(4));
            var occupied = new CountDownLatch(1);
            var release = new CountDownLatch(1);
            try {
                cold.execute(() -> {
                    occupied.countDown();
                    await(release);
                });
                assertTrue(occupied.await(5, TimeUnit.SECONDS));
                int before = fixture.nodeIo.get(0).forces;
                var node = fixture.nodes.get(0);
                var attempt = node.reclaimDeletedLedger(fixture.context(), cold, 64, 8, Duration.ofMillis(200));
                assertEquals(SegmentProfilePhysicalDelete.Status.PENDING,
                        attempt.result().get(5, TimeUnit.SECONDS).status());
                assertFalse(attempt.completion().isDone());
                assertEquals(before, fixture.nodeIo.get(0).forces);
                assertEquals(SegmentProfilePhysicalDelete.Status.PENDING,
                        node.reclaimDeletedLedger(fixture.context(), cold, 64, 8, Duration.ofSeconds(5))
                            .result().get().status());
                release.countDown();
                attempt.completion().get(5, TimeUnit.SECONDS);
                assertEquals(before, fixture.nodeIo.get(0).forces);
                var resumed = node.reclaimDeletedLedger(fixture.context(), cold, 64, 8, Duration.ofSeconds(5));
                assertEquals(SegmentProfilePhysicalDelete.Status.REUSABLE,
                        resumed.result().get(5, TimeUnit.SECONDS).status());
                resumed.completion().get(5, TimeUnit.SECONDS);
            } finally {
                release.countDown();
                cold.shutdown();
                assertTrue(cold.awaitTermination(5, TimeUnit.SECONDS));
            }
        }
    }

