    @Test
    public void publicProfileReadonlyRefreshesActualRollingServiceEpisodesAndRejectsOldObservations() throws Exception {
        try (var episode = new PublicProfileReadonlyEpisode()) {
            var fixture = episode.fixture;
            var sdk = episode.sdk;
            sdk.enableProfileReadOnly(episode.coordinator, episode.pool, 4);
            var before = fixture.manager.readLedgerMetadata(44).get(5, TimeUnit.SECONDS);
            try (var initial = sdk.openProfileLedgerReadOnly(44, fixture.password).get(5, TimeUnit.SECONDS);
                    var entries = initial.readAsync(0, 1).get(5, TimeUnit.SECONDS)) {
                assertArrayEquals(bytes(16, 8), entries.getEntry(0).getEntryBytes());
                assertArrayEquals(bytes(16, 9), entries.getEntry(1).getEntryBytes());
            }
            assertEquals(0, episode.pool.usage().reservedConnections());
            for (int target = 0; target < 3; target++) {
                var previous = episode.episodes.get(target);
                var identity = fixture.identities.get(target);
                var oldPeer = previous.persistent.readPeer(identity.bookieId().toString()).peer();
                assertNotNull(oldPeer);
                var original = fixture.dataClients.get(target).readEntry(fixture.context(), 0)
                        .get(5, TimeUnit.SECONDS);
                assertEquals(org.apache.bookkeeper.common.profile.wire.ProfileReadEntryReplyCodec.Outcome.FOUND,
                        original.outcome());
                var address = (InetSocketAddress) fixture.listeners.get(target).localAddress();
                // Keep the borrowed registry session live; only retire the actual service and its listener.
                previous.service.close();
                for (var lane : ProfileReceiveBudget.Lane.values()) {
                    assertEquals(0, previous.budget.used(lane));
                    assertEquals(0, previous.budget.usedConnections(lane));
                }
                assertNull(previous.persistent.readPeer(identity.bookieId().toString()).peer());
                var requested = servicePolicy(previous.config, identity, 2);
                var restarted = new ServiceEpisode(fixture, target, previous.config, requested, null,
                        address, sdk.getClientCtx().getScheduler(), false, false,
                        serviceRestartHeadroom(previous.config));
                episode.episodes.add(restarted);
                restarted.replaceNode(fixture, target, true);
                var peer = restarted.persistent.readPeer(identity.bookieId().toString()).peer();
                assertNotNull(peer);
                assertEquals(oldPeer.projection().endpoint(), peer.projection().endpoint());
                assertEquals(2, peer.projection().readinessGeneration().value());
                assertArrayEquals(oldPeer.projection().storageIncarnation().value(),
                        peer.projection().storageIncarnation().value());
                assertNull(restarted.persistent.revalidatePeer(oldPeer).peer());
                var stale = ProfileNormalDataClient.connectRegistered(fixture.clientGroup, fixture.peerTls,
                        restarted.persistent, oldPeer, fixture.cold, 4, 1060, Duration.ofSeconds(5));
                try {
                    assertThrows(ExecutionException.class, () -> stale.completion().get(5, TimeUnit.SECONDS));
                } finally {
                    stale.closeAsync().get(5, TimeUnit.SECONDS);
                }
                assertEquals(0, stale.backingBytes());
                assertEquals(0, stale.codecWorkspaceBytes());
                var connected = ProfileNormalDataClient.connectRegistered(fixture.clientGroup, fixture.peerTls,
                        restarted.persistent, peer, fixture.cold, 4, 1060, Duration.ofSeconds(5));
                try {
                    var recovered = connected.completion().get(5, TimeUnit.SECONDS);
                    assertEquals(2, recovered.hello().readinessGeneration());
                    var restored = recovered.readEntry(fixture.context(), 0).get(5, TimeUnit.SECONDS);
                    assertEquals(original.outcome(), restored.outcome());
                    assertEquals(original.entry(), restored.entry());
                } finally {
                    connected.closeAsync().get(5, TimeUnit.SECONDS);
                }
                awaitProfileConnectionDrain(restarted.budget);
                try (var reader = sdk.openProfileLedgerReadOnly(44, fixture.password).get(5, TimeUnit.SECONDS);
                        var entries = reader.readAsync(0, 1).get(5, TimeUnit.SECONDS)) {
                    assertArrayEquals(bytes(16, 8), entries.getEntry(0).getEntryBytes());
                    assertArrayEquals(bytes(16, 9), entries.getEntry(1).getEntryBytes());
                    int connections = 0;
                    for (var lane : ProfileReceiveBudget.Lane.values()) {
                        connections += restarted.budget.usedConnections(lane);
                    }
                    assertEquals(2, connections);
                }
                assertEquals(before.getVersion(), fixture.manager.readLedgerMetadata(44)
                        .get(5, TimeUnit.SECONDS).getVersion());
                assertEquals(0, episode.pool.usage().reservedConnections());
                assertEquals(0, episode.pool.usage().reservedRpcSlots());
                assertEquals(0, episode.pool.backingBytes());
                assertEquals(0, episode.pool.codecWorkspaceBytes());
                awaitProfileConnectionDrain(restarted.budget);
            }
        }
    }

    @Test
    public void registeredProfileServiceRejoinsAfterUnusedBookieJvmHalts() throws Exception {
        try (var episode = new PublicProfileReadonlyEpisode(3, false, 3)) {
            var fixture = episode.fixture;
            var sdk = episode.sdk;
            int target = 2;
            var identity = fixture.identities.get(target);
            var bookieId = identity.bookieId();
            String bookie = bookieId.toString();
            var registry = episode.episodes.get(0).persistent;
            var siblings = fixture.identities.subList(0, target).stream()
                    .map(node -> registry.readPeer(node.bookieId().toString()).peer()).toList();
            siblings.forEach(peer -> assertNotNull(peer));
            var prepared = episode.episodes.get(target);
            var address = (InetSocketAddress) fixture.listeners.get(target).localAddress();
            prepared.service.close();
            awaitProfileConnectionDrain(prepared.budget);
            assertNull(registry.readPeer(bookie).peer());
            long logBytes = ServiceEpisode.CONTROL_LOG_BYTES;
            var clean = SegmentArenaControlLog.inspect(prepared.config, identity, logBytes);
            assertFalse(clean.sessionOpen());
            assertEquals(0, clean.currentAllocations());

            String readinessPath = serviceReadinessPath(bookie);
            var old = haltUnusedRegisteredService(fixture, prepared, identity, address, registry, readinessPath);
            for (var sibling : siblings) {
                assertEquals(ProfileRegistrationStore.ReadStatus.FOUND, registry.revalidatePeer(sibling).status());
            }
            var abrupt = SegmentArenaControlLog.inspect(prepared.config, identity, logBytes);
            assertTrue(abrupt.sessionOpen());
            assertEquals(clean.sessionEpoch() + 1, abrupt.sessionEpoch());
            assertEquals(clean.appliedSequence() + 1, abrupt.appliedSequence()); // Only OPEN was appended.
            assertEquals(0, abrupt.currentAllocations());
            assertEquals(0, abrupt.retiredSlots());
            assertTrue(abrupt.recordedQuarantineFiles().isEmpty());
            var journal = prepared.config.directory().resolve("arena-control");
            long resolutionOffset = Files.size(journal);

            var oldReady = fixture.zk.exists(readinessPath, false);
            var policy = servicePolicy(prepared.config, identity, 6);
            var restarted = new ServiceEpisode(fixture, target, prepared.config, policy, null,
                    address, sdk.getClientCtx().getScheduler(), false, true, serviceRestartHeadroom(prepared.config));
            episode.episodes.add(restarted);
            restarted.replaceNode(fixture, target, true);
            var fresh = registry.readPeer(bookie).peer();
            assertNotNull(fresh);
            assertEquals(old.projection().endpoint(), fresh.projection().endpoint());
            assertEquals(identity.incarnation(), fresh.projection().storageIncarnation());
            assertEquals(6, fresh.projection().readinessGeneration().value());
            assertNotEquals(old.publisherSession(), fresh.publisherSession());
            var newReady = fixture.zk.exists(readinessPath, false);
            assertEquals(oldReady.getCzxid(), newReady.getCzxid());
            assertTrue(newReady.getMzxid() > oldReady.getMzxid());
            assertTrue(newReady.getVersion() > oldReady.getVersion());
            assertEquals(fresh.publisherSession(), fixture.zk.exists(readinessPath + "/writable", false)
                    .getEphemeralOwner());
            assertNull(registry.revalidatePeer(old).peer());
            var stale = ProfileNormalDataClient.connectRegistered(fixture.clientGroup, fixture.peerTls,
                    registry, old, fixture.cold, 4, 1060, Duration.ofSeconds(5));
            try {
                assertThrows(ExecutionException.class, () -> stale.completion().get(5, TimeUnit.SECONDS));
            } finally {
                stale.closeAsync().get(5, TimeUnit.SECONDS);
            }
            assertEquals(0, stale.backingBytes());
            assertEquals(0, stale.codecWorkspaceBytes());
            assertResolvedServiceEpoch(journal, resolutionOffset, abrupt);
            System.out.printf("UW_UNUSED_SERVICE_REJOIN %s sessions=%d,%d readinessBirth=%d versions=%d,%d "
                            + "epochs=%d,%d%n", bookie, old.publisherSession(), fresh.publisherSession(),
                    newReady.getCzxid(), oldReady.getVersion(), newReady.getVersion(),
                    abrupt.sessionEpoch(), abrupt.sessionEpoch() + 1);

            var attempt = episode.pool.acquire();
            try {
                var lease = attempt.completion().get(5, TimeUnit.SECONDS);
                assertEquals(3, lease.controls().size());
                assertEquals(3, lease.data().size());
                var control = lease.controls().get(bookie).hello();
                var data = lease.data().get(bookieId).hello();
                assertEquals(6, control.readinessGeneration());
                assertEquals(6, data.readinessGeneration());
                assertArrayEquals(identity.incarnation().value(), control.storageIncarnation());
                assertArrayEquals(identity.incarnation().value(), data.storageIncarnation());
            } finally {
                attempt.closeAsync().get(5, TimeUnit.SECONDS);
            }
            episode.pool.closeAsync().get(5, TimeUnit.SECONDS);
            assertRegisteredPoolDrained(episode.pool);
            var sdkPool = episode.newPeerPool();
            sdk.enableProfile(episode.initializer, episode.coordinator, VALIDATOR, sdkPool, 4);
            byte[] first = bytes(16, 8);
            byte[] second = bytes(19, 9);
            var writer = (ProfileLedgerHandle) sdk.createProfileLedger(publicCreateRequest(fixture))
                    .get(10, TimeUnit.SECONDS);
            try {
                assertEquals(0, writer.addEntry(first));
                assertEquals(1, writer.addEntry(second));
                assertEquals(1, writer.getLastAddConfirmed());
                assertEquals(first.length + second.length, writer.getLength());
                writer.closeAsync().get(30, TimeUnit.SECONDS);
            } finally {
                writer.stopLocalWrites().get(5, TimeUnit.SECONDS);
            }
            var closed = fixture.manager.readLedgerMetadata(writer.getId()).get(5, TimeUnit.SECONDS).getValue();
            assertEquals(LedgerMetadata.State.CLOSED, closed.getState());
            assertEquals(3, closed.getEnsembleSize());
            assertEquals(3, closed.getWriteQuorumSize());
            assertEquals(3, closed.getAckQuorumSize());
            assertEquals(1, closed.getLastEntryId());
            assertEquals(first.length + second.length, closed.getLength());
            try (var reader = sdk.openProfileLedgerReadOnly(writer.getId(), fixture.password).get(5, TimeUnit.SECONDS);
                    var entries = reader.readAsync(0, 1).get(5, TimeUnit.SECONDS)) {
                assertArrayEquals(first, entries.getEntry(0).getEntryBytes());
                assertArrayEquals(second, entries.getEntry(1).getEntryBytes());
            }
            sdk.close();
            assertTrue(sdkPool.usage().closing());
            assertRegisteredPoolDrained(sdkPool);
            for (var budget : fixture.budgets) {
                awaitProfileConnectionDrain(budget);
            }
            restarted.service.close();
            restarted.assertOwnedResourcesTerminal(true);
            for (var lane : ProfileReceiveBudget.Lane.values()) {
                assertEquals(0, restarted.budget.used(lane));
            }
            var closedArena = SegmentArenaControlLog.inspect(prepared.config, identity, logBytes);
            assertEquals(abrupt.sessionEpoch() + 1, closedArena.sessionEpoch());
            assertFalse(closedArena.sessionOpen());
            assertTrue(closedArena.currentAllocations() > 0);
        }
    }

    private static void assertResolvedServiceEpoch(Path journal, long offset,
            SegmentArenaControlLog.Inspection before) throws IOException {
        try (var file = java.nio.channels.FileChannel.open(journal, java.nio.file.StandardOpenOption.READ)) {
            int frameBytes = 160;
            assertEquals(offset + 2 * frameBytes, file.size());
            long sequence = before.appliedSequence() + 1;
            for (int action : List.of(4, 2)) {
                var frame = java.nio.ByteBuffer.allocate(frameBytes);
                SegmentFileIo.readFully(file, frame, offset);
                var command = SegmentControlParser.parse(frame, SegmentControlFormat.Owner.ARENA,
                        new Generation(before.physicalGeneration()), sequence++);
                assertEquals(SegmentControlFormat.Type.DEVICE_STATE, command.type());
                long epoch = before.sessionEpoch() + (action == 4 ? 0 : 1);
                assertEquals(epoch, command.operationGeneration().value());
                assertEquals(before.sessionEpoch(), command.expectedGeneration());
                var body = command.body();
                assertEquals(1, body.getInt());
                assertEquals(action, body.getInt());
                assertEquals(epoch, body.getLong());
                offset += frameBytes;
            }
        }
    }

    private ZKProfileRegistrationStore.RegisteredPeer haltUnusedRegisteredService(Fixture fixture,
            ServiceEpisode prepared, SegmentFileHeader identity, InetSocketAddress address,
            ZKProfileRegistrationStore registry, String readinessPath) throws Exception {
        try (var child = new RegisteredServiceCrashProcess(fixture, prepared, identity, address)) {
            var old = child.awaitRegistered(fixture.zk, registry, identity, address);
            var persistent = registry.read(identity.bookieId().toString()).versionedRecord().orElseThrow();
            assertEquals(old.readiness(), persistent.record());
            assertThrows(IOException.class, () -> {
                try (var lock = SegmentDataFileLock.open(prepared.config.directory())) {
                    assertTrue(lock.lock().isValid());
                }
            });

            var connected = ProfileNormalDataClient.connectRegistered(fixture.clientGroup, fixture.peerTls,
                    registry, old, fixture.cold, 4, 1060, Duration.ofSeconds(5));
            try {
                var data = connected.completion().get(5, TimeUnit.SECONDS);
                assertEquals(5, data.hello().readinessGeneration());
                assertArrayEquals(identity.incarnation().value(), data.hello().storageIncarnation());
                var channel = dataChannel(data);
                child.halt(old);
                assertTrue(channel.closeFuture().await(5, TimeUnit.SECONDS));
            } finally {
                connected.closeAsync().get(5, TimeUnit.SECONDS);
            }
            assertEquals(0, connected.backingBytes());
            assertEquals(0, connected.codecWorkspaceBytes());

            String bookie = identity.bookieId().toString();
            awaitLostServiceRegistration(fixture.zk, registry, bookie, readinessPath);
            assertEquals(persistent, registry.read(bookie).versionedRecord().orElseThrow());
            return old;
        }
    }

    private static String serviceReadinessPath(String bookie) {
        return "/socket-service-readiness/" + java.util.Base64.getUrlEncoder().withoutPadding()
                .encodeToString(bookie.getBytes(StandardCharsets.UTF_8));
    }

    private static void awaitLostServiceRegistration(ZooKeeper zk, ZKProfileRegistrationStore registry,
            String bookie, String path) throws Exception {
        long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(15);
        while (zk.exists(path + "/writable", false) != null && System.nanoTime() < deadline) {
            LockSupport.parkNanos(TimeUnit.MILLISECONDS.toNanos(10));
        }
        assertNull(zk.exists(path + "/writable", false));
        assertNull(zk.exists(path + "/service-info", false));
        assertEquals(ProfileRegistrationStore.ReadStatus.NOT_FOUND, registry.readPeer(bookie).status());
    }

    private final class RegisteredServiceCrashProcess implements AutoCloseable {
        private final Process child;
        private final Path ready;
        private final Path output;
        private final long readinessGeneration;
        private final String nonce = UUID.randomUUID().toString();

        RegisteredServiceCrashProcess(Fixture fixture, ServiceEpisode prepared, SegmentFileHeader identity,
                InetSocketAddress address) throws Exception {
            this(fixture, prepared, identity, address, false);
        }

        RegisteredServiceCrashProcess(Fixture fixture, ServiceEpisode prepared, SegmentFileHeader identity,
                InetSocketAddress address, boolean maintenance) throws Exception {
            this(fixture, prepared, identity, address, maintenance, 5);
        }

        RegisteredServiceCrashProcess(Fixture fixture, ServiceEpisode prepared, SegmentFileHeader identity,
                InetSocketAddress address, boolean maintenance, long readinessGeneration) throws Exception {
            this.readinessGeneration = readinessGeneration;
            Path inputs = temporary.newFolder().toPath();
            Path properties = inputs.resolve("service.properties");
            ready = inputs.resolve("ready");
            output = inputs.resolve("child.log");
            var configuration = new ServerConfiguration(prepared.bootstrapConfiguration);
            configureOwnedProfileService(configuration, fixture.cluster.getZooKeeperConnectString());
            var values = new java.util.Properties();
            configuration.getKeys().forEachRemaining(name -> values.setProperty(name, configuration.getString(name)));
            try (var stream = Files.newOutputStream(properties)) {
                values.store(stream, "Disposable Profile service");
            }
            child = new ProcessBuilder(Path.of(System.getProperty("java.home"), "bin", "java").toString(),
                    "-Xmx128m", "-XX:MaxDirectMemorySize=64m", "-cp", System.getProperty("java.class.path"),
                    RegisteredProfileServiceCrashProbe.class.getName(), properties.toString(), ready.toString(),
                    nonce, identity.bookieId().toString(), identity.arenaId().toString(),
                    java.util.HexFormat.of().formatHex(identity.incarnation().value()),
                    Integer.toString(address.getPort()), Boolean.toString(maintenance),
                    Long.toString(readinessGeneration))
                    .redirectErrorStream(true).redirectOutput(output.toFile()).start();
        }

        ZKProfileRegistrationStore.RegisteredPeer awaitRegistered(ZooKeeper zk, ZKProfileRegistrationStore registry,
                SegmentFileHeader identity, InetSocketAddress address) throws Exception {
            long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(20);
            while (!Files.exists(ready) && child.isAlive() && System.nanoTime() < deadline) {
                LockSupport.parkNanos(TimeUnit.MILLISECONDS.toNanos(2));
            }
            assertTrue(Files.readString(output), Files.exists(ready) && child.isAlive());
            String bookie = identity.bookieId().toString();
            var peer = registry.readPeer(bookie).peer();
            assertNotNull(peer);
            assertEquals(readinessGeneration, peer.projection().readinessGeneration().value());
            assertEquals(identity.incarnation(), peer.projection().storageIncarnation());
            assertEquals("tls://127.0.0.1:" + address.getPort(), peer.projection().endpoint());
            assertEquals(marker(peer), Files.readString(ready));
            assertEquals(peer.publisherSession(), zk.exists(serviceReadinessPath(bookie) + "/writable", false)
                    .getEphemeralOwner());
            return peer;
        }

        void halt(ZKProfileRegistrationStore.RegisteredPeer peer) throws Exception {
            halt(peer, 'H');
        }

        void halt(ZKProfileRegistrationStore.RegisteredPeer peer, int command) throws Exception {
            child.getOutputStream().write(command);
            child.getOutputStream().flush();
            boolean halted = child.waitFor(command == 'V' ? 90
                    : command == 'R' || command == 'S' || command == 'T' ? 25 : 15,
                    TimeUnit.SECONDS);
            String log = Files.readString(output);
            assertTrue(log, halted);
            assertEquals(log, 23, child.exitValue());
            String marker = marker(peer);
            assertEquals(log, List.of("UW_PROFILE_SERVICE_READY " + marker, "UW_PROFILE_SERVICE_HALT " + marker),
                    log.lines().filter(line -> line.startsWith("UW_PROFILE_SERVICE_")).toList());
            if (command == 'T') {
                assertTrue(log, log.contains("UW_RECONSTRUCTION_TAIL_ROTATION " + marker));
            } else if (command != 'H') {
                assertTrue(log, log.contains("UW_RECONSTRUCTION_COMPACTION_CUT " + (char) command + " " + marker));
            }
            System.out.println("UW_PROFILE_SERVICE_CHILD\n" + log);
        }

        private String marker(ZKProfileRegistrationStore.RegisteredPeer peer) {
            return nonce + " " + child.pid() + " " + peer.publisherSession();
        }

        @Override
        public void close() throws Exception {
            if (child.isAlive()) {
                child.destroyForcibly();
                assertTrue(Files.readString(output), child.waitFor(5, TimeUnit.SECONDS));
            }
        }
    }

    /** Starts the original owned service, then halts it on the test command without service cleanup. */
    public static final class RegisteredProfileServiceCrashProbe {
        public static void main(String[] args) throws Exception {
            if (args.length != 9) {
                throw new IllegalArgumentException("Expected owned service crash inputs");
            }
            var configuration = new ServerConfiguration();
            configuration.loadConf(Path.of(args[0]).toUri().toURL());
            String prefix = SegmentProfileService.CONFIG_PREFIX;
            var directory = Path.of(configuration.getString(prefix + "Directory"));
            var config = new IsolatedSegmentConfig(directory, 1, configuration.getInt(prefix + "LogicalShards"),
                    configuration.getInt(prefix + "DataFiles"), configuration.getLong(prefix + "BytesPerFile"),
                    4096, configuration.getInt(prefix + "MaxPayloadBytes"),
                    configuration.getInt(prefix + "MaxPendingEntries"), "FILE_CHANNEL", "OFF", "SYSTEM", "PARK");
            var identity = new SegmentFileHeader(new StorageIncarnation(java.util.HexFormat.of().parseHex(args[5])),
                    UUID.fromString(args[4]), BookieId.parse(args[3]));
            var policy = servicePolicy(config, identity, Long.parseLong(args[8]));
            String target = args[3].substring("socket".length(), args[3].indexOf(':'));
            var settings = new SegmentProfileOwnedResources.Settings(policy,
                    "/socket-service-required-" + target + "-" + Integer.toUnsignedString(directory.hashCode()),
                    "/socket-service-readiness", "/socket-initial", ZooDefs.Ids.OPEN_ACL_UNSAFE,
                    "ledger-profile", 4, Duration.ofSeconds(5), Duration.ofMillis(100), 2, 4, 64);
            ProfilePrincipal principal = socketProfilePrincipal();
            var read = new SegmentProfileReadConfig((caller, query) -> caller.equals(principal),
                    (caller, query) -> caller.equals(principal));
            long control = SegmentControlCapacity.required(config, ServiceEpisode.CONTROL_LOG_BYTES);
            long bytes = SegmentControlCapacity.sum(4L * 1024 * 1024, control, serviceRestartHeadroom(config),
                    serviceInputMetadataBytes(config), serviceDriverMetadataBytes(config));
            if (Boolean.parseBoolean(args[7])) {
                bytes += 4L * 1024 * 1024;
            }
            var budget = new ProfileReceiveBudget(bytes, 131072 + control, 262144, 8, 8, 8);
            var address = new InetSocketAddress("127.0.0.1", Integer.parseInt(args[6]));
            var service = SegmentProfileService.withOwnedResources(configuration,
                    new SecretKeySpec(bytes(32, 7), "AES"), VALIDATOR, settings, budget, 131072, 64,
                    "socket-test", address, (caller, operation) -> caller.equals(principal),
                    (caller, scope, authority) -> caller.equals(principal) && scope.equals(authority.scope())
                            ? Decision.ALLOW : Decision.DENY, read);
            assertEquals(address, service.start(true));
            long session = ((ZooKeeper) ownedResourceField(service, "zk")).getSessionId();
            assertNotEquals(0L, session);
            String marker = args[2] + " " + ProcessHandle.current().pid() + " " + session;
            System.out.println("UW_PROFILE_SERVICE_READY " + marker);
            System.out.flush();
            Path ready = Path.of(args[1]);
            Path pending = ready.resolveSibling("ready.pending");
            Files.writeString(pending, marker);
            Files.move(pending, ready, java.nio.file.StandardCopyOption.ATOMIC_MOVE);
            int command = System.in.read();
            Runnable halt = () -> {
                System.out.println("UW_PROFILE_SERVICE_HALT " + marker);
                System.out.flush();
                Runtime.getRuntime().halt(23);
            };
            if (command == 'H') {
                halt.run();
            } else if (command == 'T') {
                rotateReconstructionControls(crashStorage(service));
                System.out.println("UW_RECONSTRUCTION_TAIL_ROTATION " + marker);
                halt.run();
            } else if (command == 'V') {
                finishRetainedTailCompaction(service, marker, halt);
            } else if (command == 'F' || command == 'M' || command == 'R' || command == 'S') {
                haltDuringCompaction(service, command, marker, halt);
            }
            throw new IllegalStateException("Expected test halt command");
        }

        private static void finishRetainedTailCompaction(SegmentProfileService service, String marker, Runnable halt)
                throws Exception {
            var storage = crashStorage(service);
            var arena = reconstructionArena(storage);
            var candidates = arena.compactionCandidates(0, -1, arena.appliedThrough()).allocations();
            assertEquals(4, candidates.size());
            var tail = candidates.get(3);
            long end = arena.sealedAllocationEnd(tail.allocationId());
            assertTrue(end < SegmentArenaControlLog.AllocationIdentity.of(tail).extentEnd());
            var failure = new AtomicReference<Throwable>();
            var result = compactReconstructionSources(storage, candidates.subList(0, 3), new SegmentFileIo(),
                    failure, 70);
            assertNull(failure.get());
            assertEquals(IsolatedSegmentStorage.CompactionStatus.RECLAIMED, result.status());
            assertEquals(3, result.freedAllocations());
            assertEquals(510, result.movedEntries());
            assertEquals(0, result.destinationBytes());
            assertEquals(tail.allocationId(), result.destinationAllocation());
            assertEquals(end, arena.sealedAllocationEnd(tail.allocationId()));
            System.out.println("UW_RECONSTRUCTION_COMPACTION_CUT V " + marker);
            halt.run();
        }

        private static IsolatedSegmentStorage crashStorage(SegmentProfileService service) throws Exception {
            var field = SegmentProfileService.class.getDeclaredField("storage");
            field.setAccessible(true);
            return (IsolatedSegmentStorage) field.get(service);
        }

        private static void haltDuringCompaction(SegmentProfileService service, int command, String marker,
                Runnable halt) throws Exception {
            var storage = crashStorage(service);
            var arena = reconstructionArena(storage);
            var victims = arena.compactionCandidates(0, -1, arena.appliedThrough()).allocations();
            assertEquals(command == 'S' ? 4 : 2, victims.size());
            if (command != 'R') {
                var tail = command == 'S' ? victims.get(victims.size() - 1) : null;
                long sealedEnd = tail == null ? -1 : arena.sealedAllocationEnd(tail.allocationId());
                if (tail != null) {
                    assertTrue(tail.expectedGeneration() > 0);
                    assertTrue(arena.planPools(List.of(new SegmentArenaControlLog.PoolRequest(
                            tail.ownerShard(), tail.ownerGeneration(), tail.streamFirstSequence(), 1)))
                            .get(0).isEmpty());
                }
                haltBeforeCompactionWrite(arena, command, marker, halt, tail, sealedEnd);
            }
            var actual = new CompletableFuture<IsolatedSegmentStorage.CompactionResult>();
            assertTrue(storage.compactAllocations(UUID.randomUUID(),
                    victims.subList(0, command == 'S' ? 3 : 2).stream()
                            .map(SegmentArenaControlLog.Allocation::allocationId).toList(),
                    new IsolatedSegmentStorage.CompactionRequest((result, failure) -> {
                        if (failure == null) {
                            actual.complete(result);
                        } else {
                            actual.completeExceptionally(failure);
                        }
                    })));
            var result = actual.get(12, TimeUnit.SECONDS);
            if (command != 'R') {
                throw new AssertionError("Compaction missed the requested write: " + result);
            }
            assertEquals(IsolatedSegmentStorage.CompactionStatus.RECLAIMED, result.status());
            assertEquals(2, result.freedAllocations());
            assertEquals(4, result.movedEntries());
            rotateReconstructionControls(storage);
            assertTrue(arena.hasUnclosedDataSession());
            assertEquals(2, arena.retiredAllocations().size());
            assertEquals(4, arena.currentMoveLocations().size());
            System.out.println("UW_RECONSTRUCTION_COMPACTION_CUT R " + marker);
            halt.run();
        }

        private static void rotateReconstructionControls(IsolatedSegmentStorage storage) throws Exception {
            var rotation = new CompletableFuture<IsolatedSegmentStorage.ControlRotationResult>();
            assertTrue(storage.rotateControls(new IsolatedSegmentStorage.ControlRotationRequest((settled, failure) -> {
                if (failure == null) {
                    rotation.complete(settled);
                } else {
                    rotation.completeExceptionally(failure);
                }
            })));
            assertEquals(IsolatedSegmentStorage.ControlRotationStatus.ROTATED,
                    rotation.get(10, TimeUnit.SECONDS).status());
        }

        private static void haltBeforeCompactionWrite(SegmentArenaControlLog arena, int command, String marker,
                Runnable halt, SegmentArenaControlLog.Allocation tail, long sealedEnd) throws Exception {
            var io = SegmentArenaControlLog.class.getDeclaredField("io");
            io.setAccessible(true);
            var target = command == 'M' || command == 'S'
                    ? SegmentControlFormat.Type.MOVE : SegmentControlFormat.Type.FREE;
            int retired = arena.retiredAllocations().size();
            var intercepted = org.mockito.Mockito.spy(new SegmentFileIo());
            org.mockito.Mockito.doAnswer(invocation -> {
                java.nio.ByteBuffer input = invocation.getArgument(1);
                if (input.getInt(input.position() + 16) == target.code) {
                    assertEquals(command == 'M', arena.currentMoveLocations().isEmpty());
                    assertEquals(retired, arena.retiredAllocations().size());
                    if (tail != null) {
                        assertFalse(arena.currentMoveLocations().stream().anyMatch(location ->
                                location.address().allocation() == tail.allocationId()
                                        && location.address().offset() >= sealedEnd));
                        System.out.println("UW_RECONSTRUCTION_RESUMED_COPY " + tail.allocationId() + " "
                                + sealedEnd + " " + arena.appliedThrough());
                    }
                    System.out.println("UW_RECONSTRUCTION_COMPACTION_CUT " + (char) command + " " + marker);
                    halt.run();
                }
                return invocation.callRealMethod();
            }).when(intercepted).writeFully(org.mockito.ArgumentMatchers.any(), org.mockito.ArgumentMatchers.any(),
                    org.mockito.ArgumentMatchers.anyLong());
            io.set(arena, intercepted);
        }
    }

    @Test
    public void wholePointRecoveryClosesOpenLedgerAfterHealthyRegisteredServiceRestart() throws Exception {
        try (var episode = new PublicProfileReadonlyEpisode(3, false, 3)) {
            var fixture = episode.fixture;
            var sdk = episode.sdk;
            var context = fixture.context();
            long ledger = context.ledgerId();
            int target = 0;
            var previous = episode.episodes.get(target);
            var identity = fixture.identities.get(target);
            var bookieId = identity.bookieId();
            var oldPeer = previous.persistent.readPeer(bookieId.toString()).peer();
            assertNotNull(oldPeer);
            byte[] first = bytes(16, 8);
            byte[] second = bytes(19, 9);
            long length = first.length + second.length;
            try {
                var initial = episode.pool.acquire();
                try {
                    var lease = initial.completion().get(5, TimeUnit.SECONDS);
                    assertEquals(1, lease.data().get(bookieId).hello().readinessGeneration());
                    fixture.clients.putAll(lease.controls());
                    var available = fixture.initialize().get(5, TimeUnit.SECONDS);
                    var writer = ProfileLedgerHandle.fromInitialAvailability(sdk.getClientCtx(), available,
                            lease.data(), 8, 1024, 3, Duration.ofSeconds(5), Duration.ofMillis(5));
                    try {
                        assertEquals(0, writer.addEntry(first));
                        assertEquals(1, writer.addEntry(second));
                        assertEquals(1, writer.getLastAddConfirmed());
                        assertEquals(length, writer.getLength());
                    } finally {
                        writer.stopLocalWrites().get(5, TimeUnit.SECONDS);
                    }
                } finally {
                    fixture.clients.clear();
                    initial.closeAsync().get(5, TimeUnit.SECONDS);
                }
                assertRegisteredPoolDrained(episode.pool);
                var metadata = new ProfileLedgerMetadataStore(fixture.zk, (AbstractZkLedgerManager) fixture.manager,
                        ZooDefs.Ids.OPEN_ACL_UNSAFE, Duration.ofSeconds(5));
                var open = metadata.readMembership(ledger).snapshot();
                assertNotNull(open);
                assertEquals(LedgerMetadata.State.OPEN, open.metadata().getValue().getState());
                var root = fixture.reservations.read(ledger).snapshot();
                assertNotNull(root);

                var listener = fixture.listeners.get(target);
                var address = (InetSocketAddress) listener.localAddress();
                previous.service.close();
                assertTrue(listener.closeFuture().isSuccess());
                for (var lane : ProfileReceiveBudget.Lane.values()) {
                    assertEquals(0, previous.budget.used(lane));
                    assertEquals(0, previous.budget.usedConnections(lane));
                }
                assertNull(previous.persistent.readPeer(bookieId.toString()).peer());
                var policy = servicePolicy(previous.config, identity, 2);
                var restarted = new ServiceEpisode(fixture, target, previous.config, policy, null,
                        address, sdk.getClientCtx().getScheduler(), false, false,
                        serviceRestartHeadroom(previous.config));
                episode.episodes.add(restarted);
                restarted.replaceNode(fixture, target, true);
                var peer = restarted.persistent.readPeer(bookieId.toString()).peer();
                assertNotNull(peer);
                assertEquals(oldPeer.projection().endpoint(), peer.projection().endpoint());
                assertEquals(oldPeer.projection().storageIncarnation(), peer.projection().storageIncarnation());
                assertEquals(2, peer.projection().readinessGeneration().value());
                assertNull(restarted.persistent.revalidatePeer(oldPeer).peer());
                var stale = ProfileNormalDataClient.connectRegistered(fixture.clientGroup, fixture.peerTls,
                        restarted.persistent, oldPeer, fixture.cold, 4, 1060, Duration.ofSeconds(5));
                try {
                    assertThrows(ExecutionException.class, () -> stale.completion().get(5, TimeUnit.SECONDS));
                } finally {
                    stale.closeAsync().get(5, TimeUnit.SECONDS);
                }
                assertEquals(0, stale.backingBytes());
                assertEquals(0, stale.codecWorkspaceBytes());
                awaitProfileConnectionDrain(restarted.budget);
                var stillOpen = fixture.manager.readLedgerMetadata(ledger).get(5, TimeUnit.SECONDS);
                assertEquals(open.metadata().getVersion(), stillOpen.getVersion());
                assertEquals(LedgerMetadata.State.OPEN, stillOpen.getValue().getState());

                var fresh = episode.pool.acquire();
                try {
                    var lease = fresh.completion().get(5, TimeUnit.SECONDS);
                    var control = lease.controls().get(bookieId.toString()).hello();
                    var data = lease.data().get(bookieId).hello();
                    assertEquals(2, control.readinessGeneration());
                    assertEquals(2, data.readinessGeneration());
                    assertArrayEquals(identity.incarnation().value(), control.storageIncarnation());
                    assertArrayEquals(identity.incarnation().value(), data.storageIncarnation());
                    var recovered = episode.coordinator.recover(ledger, bytes(16, 31), sdk.getClientCtx(),
                            fixture.descriptorBytes, VALIDATOR, fixture.credential, lease.data(), lease.controls(),
                            4, Duration.ofSeconds(30)).get(35, TimeUnit.SECONDS);
                    assertEquals(recovered.reason().toString(),
                            ProfileRecoveryCoordinator.RecoveryStatus.RECOVERED_AND_CLOSED, recovered.status());
                    assertEquals(1, recovered.prefixEntryId());
                    assertEquals(length, recovered.prefixLength());
                    assertEquals(context, recovered.context().ledger());
                    assertEquals(open.birthZxid(), recovered.context().metadataBirth());
                    assertEquals(root.birthZxid(), recovered.context().lifecycleBirthZxid());
                    assertEquals(root.lifecycle().birthId(), recovered.context().lifecycleBirth());
                    assertNotNull(recovered.publication());
                    assertEquals(recovered.context(), recovered.publication().selection().boundary().context());
                } finally {
                    fresh.closeAsync().get(5, TimeUnit.SECONDS);
                }
                assertRegisteredPoolDrained(episode.pool);
                var closed = fixture.manager.readLedgerMetadata(ledger).get(5, TimeUnit.SECONDS);
                assertEquals(LedgerMetadata.State.CLOSED, closed.getValue().getState());
                assertEquals(1, closed.getValue().getLastEntryId());
                assertEquals(length, closed.getValue().getLength());
                assertEquals(open.metadata().getValue().getAllEnsembles(), closed.getValue().getAllEnsembles());
                var readPool = episode.newPeerPool();
                sdk.enableProfileReadOnly(episode.coordinator, readPool, 4);
                try (var reader = sdk.openProfileLedgerReadOnly(ledger, fixture.password).get(5, TimeUnit.SECONDS);
                        var entries = reader.readAsync(0, 1).get(5, TimeUnit.SECONDS)) {
                    assertArrayEquals(first, entries.getEntry(0).getEntryBytes());
                    assertArrayEquals(second, entries.getEntry(1).getEntryBytes());
                }
                assertEquals(closed.getVersion(),
                        fixture.manager.readLedgerMetadata(ledger).get(5, TimeUnit.SECONDS).getVersion());
                sdk.close();
                assertTrue(readPool.usage().closing());
                assertRegisteredPoolDrained(readPool);
                for (var budget : fixture.budgets) {
                    awaitProfileConnectionDrain(budget);
                }
            } finally {
                episode.pool.closeAsync().get(5, TimeUnit.SECONDS);
            }
        }
    }

    private static void assertRegisteredPoolDrained(ProfileRecoveryPeerPool pool) {
        assertEquals(0, pool.usage().reservedConnections());
        assertEquals(0, pool.usage().reservedRpcSlots());
        assertEquals(0, pool.backingBytes());
        assertEquals(0, pool.codecWorkspaceBytes());
    }

    @Test
    public void wholePointRecoveryClosesOpenLedgerAfterThePublicWriterJvmHalts() throws Exception {
        try (var episode = new PublicProfileReadonlyEpisode(3, false, 3)) {
            var fixture = episode.fixture;
            var cohort = fixture.identities.stream().map(SegmentFileHeader::bookieId).toList();
            var originalRegistry = episode.episodes.get(0).persistent;
            var originalPeers = cohort.stream().map(bookie -> originalRegistry.readPeer(bookie.toString()).peer())
                    .toList();
            for (var peer : originalPeers) {
                assertNotNull(peer);
                assertEquals(1, peer.projection().readinessGeneration().value());
            }
            byte[] first = bytes(16, 8);
            byte[] second = bytes(19, 9);
            long length = first.length + second.length;
            long ledger = fixture.context().ledgerId();
            long writerSession = haltPublicProfileWriter(fixture, first, second);
            for (int target = 0; target < cohort.size(); target++) {
                assertTrue(fixture.listeners.get(target).isActive());
                awaitProfileConnectionDrain(fixture.budgets.get(target));
            }

            String connect = fixture.cluster.getZooKeeperConnectString();
            var watcher = new ZooKeeperWatcherBase(10000, false);
            try (var zk = new ZooKeeper(connect, 10000, watcher)) {
                watcher.waitForConnection();
                assertNotEquals(0L, zk.getSessionId());
                assertNotEquals(writerSession, zk.getSessionId());
                assertNotEquals(fixture.zk.getSessionId(), zk.getSessionId());
                var registry = new ZKProfileRegistrationStore(zk, "/socket-service-readiness",
                        ZooDefs.Ids.OPEN_ACL_UNSAFE, Duration.ofSeconds(5));
                for (var peer : originalPeers) {
                    assertEquals(org.apache.bookkeeper.common.profile.startup.ProfileRegistrationStore.ReadStatus.FOUND,
                            registry.revalidatePeer(peer).status());
                }
                ProfileRecoveryPeerPool readPool;
                var config = profileWriterCrashClientConfig(connect);
                try (var factory = profileWriterCrashMetadataFactory(config, zk);
                        var manager = (AbstractZkLedgerManager) factory.newLedgerManager();
                        var sdk = BookKeeper.forConfig(config).zk(zk).eventLoopGroup(fixture.clientGroup).build()) {
                    var metadata = new ProfileLedgerMetadataStore(zk, manager,
                            ZooDefs.Ids.OPEN_ACL_UNSAFE, Duration.ofSeconds(5));
                    var reservations = new ZKProfileReservationStore(zk, "/socket-initial",
                            ZooDefs.Ids.OPEN_ACL_UNSAFE, Duration.ofSeconds(5));
                    var open = metadata.readMembership(ledger).snapshot();
                    assertNotNull(open);
                    var value = open.metadata().getValue();
                    assertEquals(LedgerMetadata.State.OPEN, value.getState());
                    assertEquals(3, value.getEnsembleSize());
                    assertEquals(3, value.getWriteQuorumSize());
                    assertEquals(3, value.getAckQuorumSize());
                    assertEquals(cohort, value.getEnsembleAt(0));
                    var root = reservations.read(ledger).snapshot();
                    assertNotNull(root);
                    assertEquals(ProfileLifecycleHead.State.READY, root.lifecycle().state());
                    assertEquals(fixture.reservation, root.reservation());

                    var coordinator = new ProfileRecoveryCoordinator(reservations, metadata, fixture.cold);
                    var pool = new ProfileRecoveryPeerPool(registry, fixture.clientGroup, fixture.peerTls,
                            fixture.cold, cohort, new ProfileRecoveryPeerPool.Limits(6, 12, 2, 1060,
                                    Duration.ofSeconds(5)));
                    ProfileRecoveryCoordinator.RecoveryResult recovered;
                    try {
                        var attempt = pool.acquire();
                        try {
                            var lease = attempt.completion().get(5, TimeUnit.SECONDS);
                            assertEquals(3, lease.controls().size());
                            assertEquals(3, lease.data().size());
                            recovered = coordinator.recover(ledger, bytes(16, 31), sdk.getClientCtx(),
                                    fixture.descriptorBytes, VALIDATOR, fixture.credential, lease.data(),
                                    lease.controls(), 4, Duration.ofSeconds(30)).get(35, TimeUnit.SECONDS);
                        } finally {
                            attempt.closeAsync().get(5, TimeUnit.SECONDS);
                        }
                    } finally {
                        pool.closeAsync().get(5, TimeUnit.SECONDS);
                    }
                    assertRegisteredPoolDrained(pool);
                    assertEquals(recovered.reason().toString(),
                            ProfileRecoveryCoordinator.RecoveryStatus.RECOVERED_AND_CLOSED, recovered.status());
                    assertEquals(1, recovered.prefixEntryId());
                    assertEquals(length, recovered.prefixLength());
                    assertEquals(fixture.context(), recovered.context().ledger());
                    assertEquals(open.birthZxid(), recovered.context().metadataBirth());
                    assertEquals(root.birthZxid(), recovered.context().lifecycleBirthZxid());
                    assertEquals(root.lifecycle().birthId(), recovered.context().lifecycleBirth());
                    assertNotNull(recovered.publication());
                    var boundary = recovered.publication().selection().boundary();
                    assertEquals(recovered.context(), boundary.context());
                    assertEquals(1, boundary.prefixEntryId());
                    assertEquals(length, boundary.prefixLength());

                    var closed = metadata.readMembership(ledger).snapshot();
                    assertNotNull(closed);
                    var published = recovered.publication().metadata();
                    assertEquals(published.birthZxid(), closed.birthZxid());
                    assertEquals(published.metadata().getVersion(), closed.metadata().getVersion());
                    assertEquals(open.birthZxid(), closed.birthZxid());
                    var closedValue = closed.metadata().getValue();
                    var serde = new org.apache.bookkeeper.meta.LedgerMetadataSerDe();
                    assertArrayEquals(serde.serialize(published.metadata().getValue()), serde.serialize(closedValue));
                    assertEquals(LedgerMetadata.State.CLOSED, closedValue.getState());
                    assertEquals(1, closedValue.getLastEntryId());
                    assertEquals(length, closedValue.getLength());
                    assertEquals(value.getAllEnsembles(), closedValue.getAllEnsembles());
                    for (var budget : fixture.budgets) {
                        awaitProfileConnectionDrain(budget);
                    }

                    readPool = new ProfileRecoveryPeerPool(registry, fixture.clientGroup, fixture.peerTls,
                            fixture.cold, cohort, new ProfileRecoveryPeerPool.Limits(6, 12, 2, 1060,
                                    Duration.ofSeconds(5)));
                    sdk.enableProfileReadOnly(coordinator, readPool, 4);
                    try (var reader = sdk.openProfileLedgerReadOnly(ledger, fixture.password).get(5, TimeUnit.SECONDS);
                            var entries = reader.readAsync(0, 1).get(5, TimeUnit.SECONDS)) {
                        assertArrayEquals(first, entries.getEntry(0).getEntryBytes());
                        assertArrayEquals(second, entries.getEntry(1).getEntryBytes());
                    }
                    assertEquals(closed.metadata().getVersion(), sdk.getLedgerManager().readLedgerMetadata(ledger)
                            .get(5, TimeUnit.SECONDS).getVersion());
                }
                assertTrue(readPool.usage().closing());
                assertRegisteredPoolDrained(readPool);
                for (var budget : fixture.budgets) {
                    awaitProfileConnectionDrain(budget);
                }
            }
        }
    }

    private long haltPublicProfileWriter(Fixture fixture, byte[] first, byte[] second) throws Exception {
        var request = publicCreateRequest(fixture);
        var encoder = java.util.Base64.getEncoder();
        var inputs = new java.util.Properties();
        String nonce = UUID.randomUUID().toString();
        inputs.setProperty("nonce", nonce);
        inputs.setProperty("zk", fixture.cluster.getZooKeeperConnectString());
        inputs.setProperty("metadata", encoder.encodeToString(
                new org.apache.bookkeeper.meta.LedgerMetadataSerDe().serialize(request.desired())));
        inputs.setProperty("backlink", encoder.encodeToString(request.reservation().backlink().encode()));
        inputs.setProperty("descriptor", encoder.encodeToString(request.descriptor()));
        inputs.setProperty("readyOperation", encoder.encodeToString(request.readyOperationId()));
        inputs.setProperty("readyPayload", encoder.encodeToString(request.readyPayloadIdentity()));
        inputs.setProperty("first", encoder.encodeToString(first));
        inputs.setProperty("second", encoder.encodeToString(second));
        var installs = request.reservation().installs();
        var install = installs.get(0);
        inputs.setProperty("installOperation", encoder.encodeToString(install.operationId()));
        inputs.setProperty("installPayload", encoder.encodeToString(install.publicSemanticPayloadIdentity()));
        inputs.setProperty("authorityDomain", install.authorityDomain());
        inputs.setProperty("authorityGeneration", Long.toString(install.authorityGeneration()));
        for (int target = 0; target < installs.size(); target++) {
            var scope = installs.get(target);
            inputs.setProperty("bookie" + target, scope.targetBookie());
            inputs.setProperty("incarnation" + target, encoder.encodeToString(scope.targetStorageIncarnation()));
        }
        Path directory = temporary.newFolder().toPath();
        Path properties = directory.resolve("writer.properties");
        Path output = directory.resolve("writer.log");
        try (var stream = Files.newOutputStream(properties)) {
            inputs.store(stream, "Disposable writer crash inputs");
        }
        var process = new ProcessBuilder(Path.of(System.getProperty("java.home"), "bin", "java").toString(),
                "-Xmx128m", "-XX:MaxDirectMemorySize=64m", "-cp", System.getProperty("java.class.path"),
                PublicProfileWriterCrashProbe.class.getName(), properties.toString())
                .redirectErrorStream(true).redirectOutput(output.toFile()).start();
        try {
            boolean exited = process.waitFor(45, TimeUnit.SECONDS);
            String log = Files.readString(output);
            assertTrue(log, exited);
            assertEquals(log, 23, process.exitValue());
            String prefix = "UW_PROFILE_WRITER_HALT " + nonce + " " + process.pid() + " "
                    + request.desired().getLedgerId() + " 1 " + (first.length + second.length) + " ";
            var markers = log.lines().filter(line -> line.startsWith("UW_PROFILE_WRITER_HALT ")).toList();
            assertEquals(log, 1, markers.size());
            String marker = markers.get(0);
            assertTrue(log, marker.startsWith(prefix));
            long session = Long.parseLong(marker.substring(prefix.length()));
            assertNotEquals(0L, session);
            System.out.println(marker);
            return session;
        } finally {
            if (process.isAlive()) {
                process.destroyForcibly();
                assertTrue("Writer test JVM did not exit during cleanup", process.waitFor(5, TimeUnit.SECONDS));
            }
        }
    }

    private static ClientConfiguration profileWriterCrashClientConfig(String connect) {
        var config = new ClientConfiguration();
        config.setMetadataServiceUri("zk+longhierarchical://" + connect + "/socket-ledgers");
        config.setUseV2WireProtocol(false);
        config.setExplictLacInterval(0);
        config.setDelayEnsembleChange(true);
        config.setAddEntryQuorumTimeout(5);
        return config;
    }

    private static org.apache.bookkeeper.meta.LedgerManagerFactory profileWriterCrashMetadataFactory(
            ClientConfiguration config, ZooKeeper zk) throws IOException {
        var factory = new LongHierarchicalLedgerManagerFactory();
        return factory.initialize(config, new ZkLayoutManager(zk, "/socket-ledgers", ZooDefs.Ids.OPEN_ACL_UNSAFE),
                factory.getCurrentVersion());
    }

    /** Separate SDK process that exits immediately after the two application-visible acknowledgements. */
    public static final class PublicProfileWriterCrashProbe {
        public static void main(String[] args) throws Exception {
            var inputs = new java.util.Properties();
            try (var stream = Files.newInputStream(Path.of(args[0]))) {
                inputs.load(stream);
            }
            var decoder = java.util.Base64.getDecoder();
            byte[] descriptor = decoder.decode(inputs.getProperty("descriptor"));
            var descriptorIdentity = ProfileDescriptorCodec.identityOf(
                    ProfileDescriptorCodec.decode(descriptor, VALIDATOR), VALIDATOR);
            var backlink = ProfileMetadataBacklink.decode(decoder.decode(inputs.getProperty("backlink")));
            var desired = new org.apache.bookkeeper.meta.LedgerMetadataSerDe().parseConfig(
                    decoder.decode(inputs.getProperty("metadata")), backlink.ledgerId(), java.util.Optional.empty());
            String domain = inputs.getProperty("authorityDomain");
            long generation = Long.parseLong(inputs.getProperty("authorityGeneration"));
            byte[] installOperation = decoder.decode(inputs.getProperty("installOperation"));
            byte[] installPayload = decoder.decode(inputs.getProperty("installPayload"));
            var cohort = new ArrayList<BookieId>();
            var installs = new ArrayList<ProfileControlScope>();
            for (int target = 0; target < desired.getEnsembleSize(); target++) {
                var bookie = BookieId.parse(inputs.getProperty("bookie" + target));
                byte[] incarnation = decoder.decode(inputs.getProperty("incarnation" + target));
                cohort.add(bookie);
                installs.add(new ProfileControlScope(ProfileControlOperation.INSTALL,
                        ProfileAuthorityPurpose.PREPARING_INSTALL, backlink.ledgerId(), backlink.instanceId(),
                        descriptorIdentity, bookie.toString(), incarnation, domain, generation,
                        installOperation, installPayload, null));
            }
            var credential = ProtectedProfileCredential.of(1, DigestManager.generateMasterKey(desired.getPassword()));
            var request = new ProfileCreateRequest(desired, new ProfileReservation(backlink, installs), descriptor,
                    credential, decoder.decode(inputs.getProperty("readyOperation")),
                    decoder.decode(inputs.getProperty("readyPayload")),
                    new ProfileCreateRequest.WriterLimits(8, 1024, 3, Duration.ofSeconds(5),
                            Duration.ofMillis(5), 4, Duration.ofSeconds(30)));
            byte[] first = decoder.decode(inputs.getProperty("first"));
            byte[] second = decoder.decode(inputs.getProperty("second"));
            String connect = inputs.getProperty("zk");
            var loops = new NioEventLoopGroup(1);
            var cold = new ThreadPoolExecutor(4, 4, 0, TimeUnit.MILLISECONDS, new ArrayBlockingQueue<>(32));
            var watcher = new ZooKeeperWatcherBase(10000, false);
            try (var zk = new ZooKeeper(connect, 10000, watcher)) {
                watcher.waitForConnection();
                var config = profileWriterCrashClientConfig(connect);
                try (var factory = profileWriterCrashMetadataFactory(config, zk);
                        var manager = (AbstractZkLedgerManager) factory.newLedgerManager();
                        var sdk = BookKeeper.forConfig(config).zk(zk).eventLoopGroup(loops).build()) {
                    var metadata = new ProfileLedgerMetadataStore(zk, manager,
                            ZooDefs.Ids.OPEN_ACL_UNSAFE, Duration.ofSeconds(5));
                    var reservations = new ZKProfileReservationStore(zk, "/socket-initial",
                            ZooDefs.Ids.OPEN_ACL_UNSAFE, Duration.ofSeconds(5));
                    var registry = new ZKProfileRegistrationStore(zk, "/socket-service-readiness",
                            ZooDefs.Ids.OPEN_ACL_UNSAFE, Duration.ofSeconds(5));
                    var tls = SslContextBuilder.forClient().sslProvider(SslProvider.JDK)
                            .keyManager(new File(certificate("client-cert.pem")),
                                    new File(certificate("client-key.pem")))
                            .trustManager(new File(certificate("server-san-cert.pem"))).protocols("TLSv1.3").build();
                    var pool = new ProfileRecoveryPeerPool(registry, loops, tls, cold, cohort,
                            new ProfileRecoveryPeerPool.Limits(6, 12, 2, 1060, Duration.ofSeconds(5)));
                    sdk.enableProfile(new ProfileInitialLifecycleCoordinator(reservations, metadata, VALIDATOR, cold),
                            new ProfileRecoveryCoordinator(reservations, metadata, cold), VALIDATOR, pool, 4);
                    var writer = sdk.createProfileLedger(request).get(10, TimeUnit.SECONDS);
                    assertEquals(backlink.ledgerId(), writer.getId());
                    assertEquals(0, writer.addEntry(first));
                    assertEquals(1, writer.addEntry(second));
                    assertEquals(1, writer.getLastAddConfirmed());
                    assertEquals(first.length + second.length, writer.getLength());
                    System.out.println("UW_PROFILE_WRITER_HALT " + inputs.getProperty("nonce") + " "
                            + ProcessHandle.current().pid() + " " + writer.getId() + " "
                            + writer.getLastAddConfirmed() + " " + writer.getLength() + " " + zk.getSessionId());
                    System.out.flush();
                    Runtime.getRuntime().halt(23);
                }
            } finally {
                cold.shutdownNow();
                try {
                    assertTrue(cold.awaitTermination(5, TimeUnit.SECONDS));
                } finally {
                    loops.shutdownGracefully(0, 5, TimeUnit.SECONDS).syncUninterruptibly();
                }
            }
        }
    }

    private static void awaitProfileConnectionDrain(ProfileReceiveBudget budget) {
        long until = System.nanoTime() + TimeUnit.SECONDS.toNanos(5);
        while (java.util.Arrays.stream(ProfileReceiveBudget.Lane.values())
                .anyMatch(lane -> budget.usedConnections(lane) != 0) && System.nanoTime() < until) {
            LockSupport.parkNanos(TimeUnit.MILLISECONDS.toNanos(1));
        }
        for (var lane : ProfileReceiveBudget.Lane.values()) {
            assertEquals(0, budget.usedConnections(lane));
        }
    }

    @Test
    public void publicProfileReadonlySdkUsesOwnedRegisteredPeersAndPreservesDefaultBoundary() throws Exception {
        try (var episode = new PublicProfileReadonlyEpisode()) {
            var sdk = episode.sdk;
            var fixture = episode.fixture;
            var before = fixture.manager.readLedgerMetadata(44).get();
            assertEquals(BKException.Code.IllegalOpException, BKException.getExceptionCode(assertThrows(
                    ExecutionException.class, () -> sdk.openProfileLedgerReadOnly(44, fixture.password)
                            .get(5, TimeUnit.SECONDS))));
            assertThrows(IllegalArgumentException.class,
                    () -> sdk.enableProfileReadOnly(episode.coordinator, episode.pool, 0));
            sdk.enableProfileReadOnly(episode.coordinator, episode.pool, 4);
            assertThrows(BKException.class, () -> sdk.enableProfileReadOnly(episode.coordinator, episode.pool, 4));
            assertThrows(IllegalStateException.class, episode.pool::acquire);
            assertThrows(IllegalStateException.class, episode.pool::closeAsync);
            assertEquals(BKException.Code.UnauthorizedAccessException, BKException.getExceptionCode(assertThrows(
                    ExecutionException.class, () -> sdk.openProfileLedgerReadOnly(44, bytes(8, 99))
                            .get(5, TimeUnit.SECONDS))));
            assertEquals(0, episode.pool.usage().reservedConnections());
            var handle = sdk.openProfileLedgerReadOnly(44, fixture.password).get(5, TimeUnit.SECONDS);
            assertEquals(1, handle.getLastAddConfirmed());
            assertEquals(32, handle.getLength());
            assertEquals(6, episode.pool.usage().reservedConnections());
            assertEquals(BKException.Code.TooManyRequestsException, BKException.getExceptionCode(assertThrows(
                    ExecutionException.class, () -> sdk.openProfileLedgerReadOnly(44, fixture.password)
                            .get(5, TimeUnit.SECONDS))));
            assertEquals(BKException.Code.IllegalOpException, BKException.getExceptionCode(assertThrows(
                    ExecutionException.class, () -> sdk.newOpenLedgerOp().withLedgerId(44)
                            .withPassword(fixture.password).withRecovery(false).execute().get(5, TimeUnit.SECONDS))));
            var entered = new CountDownLatch(1);
            var release = new CountDownLatch(1);
            sdk.getClientCtx().getMainWorkerPool().executeOrdered(44L, () -> {
                entered.countDown();
                await(release);
            });
            try {
                assertTrue(entered.await(5, TimeUnit.SECONDS));
                var read = handle.readAsync(0, 1).thenAccept(entries -> {
                    try (entries) {
                        assertArrayEquals(bytes(16, 8), entries.getEntry(0).getEntryBytes());
                        assertArrayEquals(bytes(16, 9), entries.getEntry(1).getEntryBytes());
                        assertEquals(BKException.Code.IllegalOpException,
                                assertThrows(BKException.class, sdk::close).getCode());
                    }
                });
                release.countDown();
                read.get(5, TimeUnit.SECONDS);
            } finally {
                release.countDown();
            }
            assertFalse(sdk.getClientCtx().isClientClosed());
            fixture.clientGroup.next().submit(() -> assertEquals(BKException.Code.IllegalOpException,
                    assertThrows(BKException.class, sdk::close).getCode())).get(5, TimeUnit.SECONDS);
            assertFalse(sdk.getClientCtx().isClientClosed());
            var next = new AtomicReference<CompletableFuture<org.apache.bookkeeper.client.LedgerHandle>>();
            handle.closeAsync().thenRun(() -> next.set(sdk.openProfileLedgerReadOnly(44, fixture.password)))
                    .get(5, TimeUnit.SECONDS);
            var reopened = next.get().get(5, TimeUnit.SECONDS);
            try (var entries = reopened.readAsync(1, 1).get(5, TimeUnit.SECONDS)) {
                assertArrayEquals(bytes(16, 9), entries.getEntry(1).getEntryBytes());
            }
            assertEquals(before.getVersion(), fixture.manager.readLedgerMetadata(44).get().getVersion());
            sdk.close();
            assertEquals(0, episode.pool.usage().reservedConnections());
            assertEquals(0, episode.pool.usage().reservedRpcSlots());
            assertEquals(0, episode.pool.backingBytes());
            assertTrue(sdk.getClientCtx().getMainWorkerPool().isShutdown());
            assertFalse(fixture.clientGroup.isShuttingDown());
            assertEquals(BKException.Code.ClientClosedException, BKException.getExceptionCode(assertThrows(
                    ExecutionException.class, () -> reopened.readAsync(0, 0).get(5, TimeUnit.SECONDS))));
        }
    }

    @Test
    public void publicProfileReadonlySdkCloseWaitsForCancelledColdOpenBeforeClosingDependencies() throws Exception {
        try (var episode = new PublicProfileReadonlyEpisode()) {
            var fixture = episode.fixture;
            var sdk = episode.sdk;
            var watcher = new ZooKeeperWatcherBase(10000, false);
            try (var held = new HoldReadonlyMetadataClient(fixture.cluster.getZooKeeperConnectString(), watcher)) {
                held.metadataPath = ((AbstractZkLedgerManager) fixture.manager).getLedgerPath(44);
                var metadata = new ProfileLedgerMetadataStore(held, (AbstractZkLedgerManager) fixture.manager,
                        ZooDefs.Ids.OPEN_ACL_UNSAFE, Duration.ofSeconds(5));
                var store = new ZKProfileReservationStore(held, "/socket-initial",
                        ZooDefs.Ids.OPEN_ACL_UNSAFE, Duration.ofSeconds(5));
                sdk.enableProfileReadOnly(new ProfileRecoveryCoordinator(store, metadata, fixture.cold),
                        episode.pool, 4);
                var opened = sdk.openProfileLedgerReadOnly(44, fixture.password);
                assertTrue(held.held.await(5, TimeUnit.SECONDS));
                assertTrue(opened.cancel(false));
                var closed = new CompletableFuture<Void>();
                var started = new CountDownLatch(1);
                var stopper = new Thread(() -> {
                    started.countDown();
                    try {
                        sdk.close();
                        closed.complete(null);
                    } catch (Throwable failure) {
                        closed.completeExceptionally(failure);
                    }
                }, "sdk-profile-cold-close");
                stopper.start();
                try {
                    assertTrue(started.await(5, TimeUnit.SECONDS));
                    assertThrows(java.util.concurrent.TimeoutException.class,
                            () -> closed.get(150, TimeUnit.MILLISECONDS));
                    assertEquals(6, episode.pool.usage().reservedConnections());
                    assertFalse(sdk.getClientCtx().getMainWorkerPool().isShutdown());
                    assertFalse(sdk.getClientCtx().getScheduler().isShutdown());
                    assertEquals(LedgerMetadata.State.CLOSED, sdk.getClientCtx().getLedgerManager()
                            .readLedgerMetadata(44).get(5, TimeUnit.SECONDS).getValue().getState());
                } finally {
                    held.release.run();
                }
                closed.get(15, TimeUnit.SECONDS);
                stopper.join(5000);
                assertFalse(stopper.isAlive());
                assertEquals(0, episode.pool.usage().reservedConnections());
                assertTrue(opened.isCancelled());
            }
        }
    }

    @Test
    public void publicProfileReadonlySdkInterruptedCloseRetainsLeaseUntilActualReadOutputDrain() throws Exception {
        try (var episode = new PublicProfileReadonlyEpisode()) {
            var sdk = episode.sdk;
            sdk.enableProfileReadOnly(episode.coordinator, episode.pool, 4);
            var reader = sdk.openProfileLedgerReadOnly(44, episode.fixture.password).get(5, TimeUnit.SECONDS);
            var transportField = reader.getClass().getDeclaredField("transport");
            transportField.setAccessible(true);
            Object transport = transportField.get(reader);
            var clientsField = transport.getClass().getDeclaredField("clients");
            clientsField.setAccessible(true);
            @SuppressWarnings("unchecked")
            var clients = (Map<BookieId, ProfileNormalDataClient>) clientsField.get(transport);
            var held = new AtomicReference<ChannelPromise>();
            for (var peer : clients.values()) {
                Channel channel = dataChannel(peer);
                channel.eventLoop().submit(() -> channel.pipeline().addAfter(
                        channel.pipeline().context(SslHandler.class).name(), "holdPublicReaderWritePromise",
                        new ChannelOutboundHandlerAdapter() {
                            @Override
                            public void write(ChannelHandlerContext ctx, Object message, ChannelPromise promise) {
                                ByteBuf body = (ByteBuf) message;
                                if (body.getUnsignedShort(body.readerIndex() + 14)
                                        == ProfileOperation.READ_ENTRY.wireValue()
                                        && held.compareAndSet(null, promise)) {
                                    ctx.write(body, ctx.newPromise());
                                } else {
                                    ctx.write(body, promise);
                                }
                            }
                        })).get(5, TimeUnit.SECONDS);
            }
            try {
                try (var entries = reader.readAsync(0, 0).get(5, TimeUnit.SECONDS)) {
                    assertArrayEquals(bytes(16, 8), entries.getEntry(0).getEntryBytes());
                }
                assertNotNull(held.get());
                var stopped = new CompletableFuture<Throwable>();
                var started = new CountDownLatch(1);
                var stopper = new Thread(() -> {
                    started.countDown();
                    try {
                        sdk.close();
                        stopped.complete(null);
                    } catch (Throwable failure) {
                        stopped.complete(failure);
                    }
                }, "sdk-profile-read-close");
                stopper.start();
                assertTrue(started.await(5, TimeUnit.SECONDS));
                assertThrows(java.util.concurrent.TimeoutException.class,
                        () -> stopped.get(150, TimeUnit.MILLISECONDS));
                stopper.interrupt();
                assertTrue(stopped.get(5, TimeUnit.SECONDS) instanceof InterruptedException);
                stopper.join(5000);
                assertFalse(stopper.isAlive());
                assertEquals(6, episode.pool.usage().reservedConnections());
                assertFalse(sdk.getClientCtx().getMainWorkerPool().isShutdown());
                assertFalse(sdk.getClientCtx().getScheduler().isShutdown());
                assertEquals(LedgerMetadata.State.CLOSED, sdk.getClientCtx().getLedgerManager()
                        .readLedgerMetadata(44).get(5, TimeUnit.SECONDS).getValue().getState());
                held.get().setSuccess();
                sdk.close();
                assertEquals(0, episode.pool.usage().reservedConnections());
                assertEquals(0, episode.pool.backingBytes());
                sdk.close();
            } finally {
                if (held.get() != null) {
                    held.get().trySuccess();
                }
            }
        }
    }

    @Test
    public void registeredPeerPoolPinsTheLeaseAndKeepsCapacityUntilActualClose() throws Exception {
        try (Fixture fixture = new Fixture(false, false, true, 3, 2, true, true);
                var reader = registrationReader(fixture)) {
            fixture.helloReadinessGeneration = 1;
            fixture.connectAll(Duration.ofSeconds(5));
            fixture.initialize().get(5, TimeUnit.SECONDS);
            String endpoint = "tls://127.0.0.1:"
                    + ((InetSocketAddress) fixture.listeners.get(0).localAddress()).getPort();
            var registry = registeredPeer(fixture, reader, endpoint, 1,
                    fixture.identities.get(0).incarnation().value());
            var pool = new org.apache.bookkeeper.discover.profile.ProfileRecoveryPeerPool(registry,
                    fixture.clientGroup, fixture.peerTls, fixture.cold, List.of(fixture.identities.get(0).bookieId()),
                    new org.apache.bookkeeper.discover.profile.ProfileRecoveryPeerPool.Limits(
                            2, 4, 2, 1060, Duration.ofSeconds(5)));
            var acquisition = pool.acquire();
            var lease = acquisition.completion().get(5, TimeUnit.SECONDS);
            assertEquals(2, pool.usage().reservedConnections());
            assertEquals(4, pool.usage().reservedRpcSlots());
            assertTrue(pool.backingLimitBytes() > 0);
            assertTrue(pool.backingBytes() <= pool.backingLimitBytes());
            assertTrue(pool.usage().borrowed());
            var unavailable = pool.acquire();
            assertThrows(ExecutionException.class, () -> unavailable.completion().get(5, TimeUnit.SECONDS));
            unavailable.closeAsync().get(5, TimeUnit.SECONDS);
            assertEquals(2, pool.usage().reservedConnections());
            var closing = pool.closeAsync();
            assertThrows(java.util.concurrent.TimeoutException.class,
                    () -> closing.get(150, TimeUnit.MILLISECONDS));
            var source = lease.data().get(fixture.identities.get(0).bookieId());
            evidenceEntry(fixture, source, 0, -1, 16, 16);
            assertEquals(org.apache.bookkeeper.common.profile.wire.ProfileReadEntryReplyCodec.Outcome.FOUND,
                    source.readEntry(fixture.context(), 0).get(5, TimeUnit.SECONDS).outcome());
            lease.closeAsync().get(5, TimeUnit.SECONDS);
            closing.get(5, TimeUnit.SECONDS);
            assertEquals(0, pool.usage().reservedConnections());
            assertEquals(0, pool.usage().reservedRpcSlots());
            assertEquals(0, pool.backingBytes());
            assertEquals(0, pool.backingLimitBytes());
            assertThrows(IllegalStateException.class, lease::data);
            assertFalse(fixture.clientGroup.isShuttingDown());
        }
    }

    @Test
    public void replicationWorkerConsumesRegisteredPoolAndRepairsAnActuallyUnavailablePeer() throws Exception {
        try (Fixture fixture = new Fixture(false, false, true, 4, 2, true, true);
                BookKeeper sdk = sdk(fixture);
                var reader = registrationReader(fixture)) {
            fixture.helloReadinessGeneration = 1;
            fixture.connectAll(Duration.ofSeconds(5));
            fixture.initialize().get(5, TimeUnit.SECONDS);
            var data = new HashMap<BookieId, ProfileNormalDataClient>();
            for (int node = 0; node < 3; node++) {
                var client = dataClient(fixture, node, 4, Duration.ofSeconds(5));
                data.put(fixture.identities.get(node).bookieId(), client);
                evidenceEntry(fixture, client, 0, -1, 16, 16);
            }
            var metadata = new ProfileLedgerMetadataStore(fixture.zk, (AbstractZkLedgerManager) fixture.manager,
                    ZooDefs.Ids.OPEN_ACL_UNSAFE, Duration.ofSeconds(5));
            var coordinator = new ProfileRecoveryCoordinator(fixture.reservations, metadata, fixture.cold);
            coordinator.recover(44, bytes(16, 31), sdk.getClientCtx(), fixture.descriptorBytes, VALIDATOR,
                    fixture.credential, data, fixture.clients, 3, Duration.ofSeconds(30)).get(30, TimeUnit.SECONDS);
            org.apache.bookkeeper.discover.profile.ZKProfileRegistrationStore registry = null;
            for (int node = 0; node < 4; node++) {
                String endpoint = "tls://127.0.0.1:"
                        + ((InetSocketAddress) fixture.listeners.get(node).localAddress()).getPort();
                registry = registeredPeer(fixture, reader, node, endpoint, 1,
                        fixture.identities.get(node).incarnation().value());
            }
            fixture.listeners.get(2).close().syncUninterruptibly();
            var pool = new org.apache.bookkeeper.discover.profile.ProfileRecoveryPeerPool(registry,
                    fixture.clientGroup, fixture.peerTls, fixture.cold,
                    fixture.identities.stream().map(identity -> identity.bookieId()).toList(),
                    new org.apache.bookkeeper.discover.profile.ProfileRecoveryPeerPool.Limits(
                            8, 16, 2, 1060, Duration.ofSeconds(5)));
            try (var monitor = sdk.getLedgerManagerFactory().newLedgerUnderreplicationManager()) {
                monitor.markLedgerUnderreplicated(44, "socket2:3181");
                var options = new ProfileRecoveryCoordinator.WorkerOptions(fixture.descriptorBytes, VALIDATOR,
                        Map.of(), Map.of(), 3, 8, Duration.ofSeconds(30));
                var worker = new org.apache.bookkeeper.replication.ReplicationWorker(
                        profileWorkerConfiguration(fixture), sdk, org.apache.bookkeeper.stats.NullStatsLogger.INSTANCE,
                        coordinator, options, pool);
                worker.start();
                try {
                    awaitProfileWorkerStarted(worker);
                    long until = System.nanoTime() + TimeUnit.SECONDS.toNanos(15);
                    while (monitor.getLedgerUnreplicationInfo(44) != null && System.nanoTime() < until) {
                        LockSupport.parkNanos(TimeUnit.MILLISECONDS.toNanos(1));
                    }
                    assertNull(monitor.getLedgerUnreplicationInfo(44));
                    assertEquals(fixture.identities.get(3).bookieId(),
                            fixture.manager.readLedgerMetadata(44).get().getValue().getAllEnsembles().get(0L).get(2));
                    assertEquals(0, pool.usage().reservedConnections());
                } finally {
                    worker.shutdown();
                    pool.closeAsync().get(5, TimeUnit.SECONDS);
                }
            }
        }
    }

